package com.droplogger;

/**
 * DEV ONLY, never shipped: the "dev" source set is not part of the plugin jar. runClient puts this
 * class ahead of the real PlatformEndpoint on its classpath, so a local dev client can talk to the
 * private dev API (for example http://127.0.0.1:3002 through an SSH tunnel) when SOLUS_DEV_API is
 * set. Without it, this returns the same live URL as the shipped class.
 */
final class PlatformEndpoint
{
    private static final String LIVE_URL = "https://api.solusosrs.com";

    private PlatformEndpoint()
    {
    }

    static String url()
    {
        String dev = System.getenv("SOLUS_DEV_API");
        return dev != null && !dev.isEmpty() ? dev : LIVE_URL;
    }
}

package com.droplogger;

import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

public class AdminPanel extends JPanel implements Scrollable
{
    // The admin tab's scroll pane forbids horizontal scrolling; without tracking the
    // viewport width, any component wider than the sidebar is silently CLIPPED.
    @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
    @Override public int getScrollableUnitIncrement(Rectangle r, int o, int d) { return 14; }
    @Override public int getScrollableBlockIncrement(Rectangle r, int o, int d) { return 100; }
    @Override public boolean getScrollableTracksViewportWidth() { return true; }
    @Override public boolean getScrollableTracksViewportHeight() { return false; }

    private static final Font SECTION_FONT = new Font("Segoe UI", Font.BOLD, 12);
    private static final Font LABEL_FONT = new Font("Segoe UI", Font.PLAIN, 11);
    private static final Font SMALL_FONT = new Font("Segoe UI", Font.PLAIN, 11);
    private static final Font SMALL_ITALIC = new Font("Segoe UI", Font.ITALIC, 11);

    private final JLabel statusLabel = new JLabel("Admin ready");

    // ── Shared Settings (managed via web dashboard) ──

    // ── Weekly Events ──
    private final JComboBox<String> eventTypeBox = new JComboBox<>(new String[]{"Boss of the Week", "Skill of the Week", "Gamer of the Week", "Clue Hunter of the Week"});
    private final JComboBox<String> eventMetricBox = new JComboBox<>();
    private final JTextField eventNameField = new JTextField();
    private final JTextField eventStartField = new JTextField();
    private final JTextField eventEndField = new JTextField();
    private final JPanel eventsListPanel = new JPanel();
    private Runnable onLoadEvents;
    private Consumer<String> onCancelEvent;

    // ── Rotate API Key ──
    private final JTextField newApiKeyField = new JTextField();
    private final JLabel newBoardCodeLabel = new JLabel(" ");

    // ── Announcements ──
    private final JPanel announcementsListPanel = new JPanel();
    private final JTextArea announcementInput = new JTextArea(2, 20);
    private final JCheckBox announcementPinned = new JCheckBox("Pin");
    private Consumer<Object[]> onCreateAnnouncement;     // {String message, Boolean pinned}
    private Consumer<String[]> onEditAnnouncement;       // {id, message}
    private Consumer<Object[]> onTogglePinAnnouncement;  // {String id, Boolean pinned}
    private Consumer<String> onDeleteAnnouncement;       // id

    // Callbacks
    private Consumer<String[]> onSaveSettings;
    private Runnable onLoadSettings;
    private Consumer<String[]> onRemoveHiscore;
    private Consumer<String> onRotateApiKey;
    private Consumer<String[]> onStartEvent; // {type, metric, name, days, startsInDays}
    private Runnable onSyncRoster;

    public AdminPanel()
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(6, 4, 6, 4));

        // Header
        JLabel header = new JLabel("Admin Tools");
        header.setFont(header.getFont().deriveFont(Font.BOLD, 13f));
        header.setForeground(new Color(255, 100, 100));
        header.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(header);
        add(Box.createVerticalStrut(8));

        // Shared settings are managed via the web dashboard

        // ══════════════════════════════════
        // Announcements
        // ══════════════════════════════════
        add(createSectionTitle("Announcements"));
        add(Box.createVerticalStrut(4));

        announcementsListPanel.setLayout(new BoxLayout(announcementsListPanel, BoxLayout.Y_AXIS));
        announcementsListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        announcementsListPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(announcementsListPanel);
        add(Box.createVerticalStrut(4));

        announcementInput.setLineWrap(true);
        announcementInput.setWrapStyleWord(true);
        announcementInput.setFont(SMALL_FONT);
        JScrollPane inputScroll = new JScrollPane(announcementInput);
        inputScroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        inputScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 44));
        add(inputScroll);
        add(Box.createVerticalStrut(2));

        JPanel addRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        addRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        addRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        addRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        announcementPinned.setBackground(ColorScheme.DARK_GRAY_COLOR);
        announcementPinned.setForeground(new Color(160, 160, 160));
        announcementPinned.setFont(SMALL_FONT);
        JButton postBtn = createButton("Post");
        postBtn.addActionListener(e -> {
            String msg = announcementInput.getText().trim();
            if (msg.isEmpty()) { setStatus("Enter an announcement"); return; }
            if (onCreateAnnouncement != null) onCreateAnnouncement.accept(new Object[]{msg, announcementPinned.isSelected()});
            announcementInput.setText("");
            announcementPinned.setSelected(false);
        });
        addRow.add(announcementPinned);
        addRow.add(postBtn);
        add(addRow);

        add(Box.createVerticalStrut(8));
        add(createSeparator());
        add(Box.createVerticalStrut(6));

        // ══════════════════════════════════
        // Weekly Events
        // ══════════════════════════════════
        add(createSectionTitle("Weekly Events"));
        add(Box.createVerticalStrut(4));

        // Upcoming + running events, refreshed from the platform
        eventsListPanel.setLayout(new BoxLayout(eventsListPanel, BoxLayout.Y_AXIS));
        eventsListPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        eventsListPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(eventsListPanel);
        add(Box.createVerticalStrut(6));

        add(createFieldLabel("Event Type"));
        eventTypeBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        eventTypeBox.setFont(SMALL_FONT);
        eventTypeBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(eventTypeBox);
        add(Box.createVerticalStrut(4));

        add(createFieldLabel("Metric"));
        eventMetricBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        eventMetricBox.setFont(SMALL_FONT);
        eventMetricBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(eventMetricBox);
        add(Box.createVerticalStrut(4));

        // Populate metric dropdown based on event type
        populateMetricBox();
        eventTypeBox.addActionListener(e -> populateMetricBox());

        add(createFieldLabel("Custom name (optional)"));
        eventNameField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        eventNameField.setFont(SMALL_FONT);
        eventNameField.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(eventNameField);
        add(Box.createVerticalStrut(4));

        add(createFieldLabel("Start \u2014 ET, blank = now (yyyy-MM-dd HH:mm)"));
        eventStartField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        eventStartField.setFont(SMALL_FONT);
        eventStartField.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(eventStartField);
        add(Box.createVerticalStrut(4));

        add(createFieldLabel("End \u2014 ET, blank = start + 7 days"));
        eventEndField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        eventEndField.setFont(SMALL_FONT);
        eventEndField.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(eventEndField);
        add(Box.createVerticalStrut(6));

        JPanel eventButtons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        eventButtons.setBackground(ColorScheme.DARK_GRAY_COLOR);
        eventButtons.setAlignmentX(Component.LEFT_ALIGNMENT);
        eventButtons.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

        JButton startEventBtn = createButton("Start / Schedule");
        startEventBtn.addActionListener(e -> {
            String typeLabel = (String) eventTypeBox.getSelectedItem();
            String metricLabel = (String) eventMetricBox.getSelectedItem();
            if (typeLabel == null || metricLabel == null) return;

            String type = EventMetrics.typeFromLabel(typeLabel);
            String metric = EventMetrics.metricFromDisplayName(metricLabel);
            if (metric == null) return;

            String startText = eventStartField.getText().trim();
            String endText = eventEndField.getText().trim();
            String custom = eventNameField.getText().trim();
            String displayName = custom.isEmpty() ? typeLabel + ": " + metricLabel : custom;

            String when = startText.isEmpty() ? "starting NOW" : "starting " + startText + " ET";
            String until = endText.isEmpty() ? "running 7 days" : "until " + endText + " ET";
            if (confirmAction("Schedule \"" + displayName + "\"?\n" + when + ", " + until + "."))
            {
                if (onStartEvent != null)
                {
                    onStartEvent.accept(new String[]{type, metric, displayName, startText, endText});
                    eventNameField.setText("");
                    eventStartField.setText("");
                    eventEndField.setText("");
                }
            }
        });

        JButton refreshEventsBtn = createButton("Refresh");
        refreshEventsBtn.addActionListener(e -> { if (onLoadEvents != null) onLoadEvents.run(); });

        eventButtons.add(startEventBtn);
        eventButtons.add(refreshEventsBtn);
        add(eventButtons);

        add(Box.createVerticalStrut(8));
        add(createSeparator());
        add(Box.createVerticalStrut(6));

        // ══════════════════════════════════
        // Clan Roster
        // ══════════════════════════════════
        add(createSectionTitle("Clan Roster"));
        add(Box.createVerticalStrut(4));

        JLabel rosterDesc = new JLabel("<html>Sync full member list &amp; ranks to the platform</html>");
        rosterDesc.setFont(SMALL_FONT);
        rosterDesc.setForeground(new Color(150, 150, 150));
        rosterDesc.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(rosterDesc);
        add(Box.createVerticalStrut(4));

        JButton syncRosterBtn = createButton("Sync Roster");
        syncRosterBtn.addActionListener(e -> {
            if (onSyncRoster != null) onSyncRoster.run();
        });
        add(syncRosterBtn);

        add(Box.createVerticalStrut(8));
        add(createSeparator());
        add(Box.createVerticalStrut(6));

        // ══════════════════════════════════
        // Rotate API Key
        // ══════════════════════════════════
        add(createSectionTitle("Rotate API Key"));
        add(Box.createVerticalStrut(4));

        add(createFieldLabel("New API Key (min 6 chars)"));
        newApiKeyField.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        newApiKeyField.setFont(SMALL_FONT);
        newApiKeyField.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(newApiKeyField);
        add(Box.createVerticalStrut(4));

        JButton rotateBtn = createButton("Rotate Key");
        rotateBtn.addActionListener(e -> {
            String newKey = newApiKeyField.getText().trim();
            if (newKey.length() < 6)
            {
                setStatus("API key must be at least 6 characters");
                return;
            }
            if (confirmAction("Rotate API key?\nAll members will need a new clan code."))
            {
                if (onRotateApiKey != null) onRotateApiKey.accept(newKey);
            }
        });
        JPanel rotatePanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        rotatePanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        rotatePanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        rotatePanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        rotatePanel.add(rotateBtn);
        add(rotatePanel);
        add(Box.createVerticalStrut(2));

        newBoardCodeLabel.setFont(SMALL_ITALIC);
        newBoardCodeLabel.setForeground(new Color(100, 200, 100));
        newBoardCodeLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(newBoardCodeLabel);

        add(Box.createVerticalStrut(8));
        add(createSeparator());
        add(Box.createVerticalStrut(6));

        // ══════════════════════════════════
        // Speed Times Moderation
        // ══════════════════════════════════
        add(createSectionTitle("Speed Times Moderation"));
        add(Box.createVerticalStrut(4));

        // Cascading dropdowns: Group → Boss → Size
        JComboBox<String> hsGroupBox = new JComboBox<>();
        JComboBox<String> hsBossBox = new JComboBox<>();
        JComboBox<String> hsSizeBox = new JComboBox<>();

        for (String groupName : BossCategory.getDisplayGroupNames())
        {
            hsGroupBox.addItem(groupName);
        }
        hsGroupBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        hsGroupBox.setFont(SMALL_FONT);
        hsBossBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        hsBossBox.setFont(SMALL_FONT);
        hsSizeBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        hsSizeBox.setFont(SMALL_FONT);

        // Wire cascading logic
        hsGroupBox.addActionListener(e -> {
            hsBossBox.removeAllItems();
            String group = (String) hsGroupBox.getSelectedItem();
            if (group == null) return;
            for (String boss : BossCategory.getBossNamesInGroup(group))
            {
                hsBossBox.addItem(boss);
            }
        });

        hsBossBox.addActionListener(e -> {
            hsSizeBox.removeAllItems();
            String group = (String) hsGroupBox.getSelectedItem();
            String boss = (String) hsBossBox.getSelectedItem();
            if (group == null || boss == null) return;
            java.util.List<BossCategory> cats = BossCategory.getCategoriesForBoss(group, boss);
            for (BossCategory cat : cats)
            {
                hsSizeBox.addItem(cat.getSizeLabel());
            }
        });

        // Initialize
        if (hsGroupBox.getItemCount() > 0)
        {
            hsGroupBox.setSelectedIndex(0);
        }

        add(createLabeledField("Group:", hsGroupBox));
        add(Box.createVerticalStrut(2));
        add(createLabeledField("Boss:", hsBossBox));
        add(Box.createVerticalStrut(2));
        add(createLabeledField("Size:", hsSizeBox));
        add(Box.createVerticalStrut(2));

        String[] ranks = {"1", "2", "3"};
        JComboBox<String> hiscoreRankBox = new JComboBox<>(ranks);
        hiscoreRankBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

        add(createLabeledField("Rank:", hiscoreRankBox));
        add(Box.createVerticalStrut(4));

        JButton removeHiscoreBtn = createButton("Remove Entry");
        removeHiscoreBtn.setAlignmentX(Component.LEFT_ALIGNMENT);
        removeHiscoreBtn.addActionListener(e -> {
            String group = (String) hsGroupBox.getSelectedItem();
            String boss = (String) hsBossBox.getSelectedItem();
            String size = (String) hsSizeBox.getSelectedItem();
            if (group == null || boss == null) return;

            // Find the matching BossCategory
            java.util.List<BossCategory> cats = BossCategory.getCategoriesForBoss(group, boss);
            BossCategory selected = null;
            if (cats.size() == 1)
            {
                selected = cats.get(0);
            }
            else if (size != null)
            {
                for (BossCategory cat : cats)
                {
                    if (cat.getSizeLabel().equals(size)) { selected = cat; break; }
                }
            }
            if (selected == null) return;

            int rank = Integer.parseInt((String) hiscoreRankBox.getSelectedItem());
            if (confirmAction("Remove rank #" + rank + " from " + selected.getDisplayName() + " (" + selected.getSizeLabel() + ")?"))
            {
                if (onRemoveHiscore != null) onRemoveHiscore.accept(new String[]{selected.getKey(), String.valueOf(rank)});
            }
        });
        add(removeHiscoreBtn);
        add(Box.createVerticalStrut(8));

        // ── Status bar ──
        add(createSeparator());
        add(Box.createVerticalStrut(4));
        statusLabel.setFont(SMALL_ITALIC);
        statusLabel.setForeground(new Color(150, 150, 150));
        statusLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(statusLabel);
    }

    // ── Public methods for populating data ──

    public void setStatus(String text)
    {
        SwingUtilities.invokeLater(() -> statusLabel.setText(text));
    }

    /** @deprecated Clan name is hardcoded to Solus. */
    public void setClanName(String name) { /* no-op */ }

    // ── Callback setters ──

    public void setOnSaveSettings(Consumer<String[]> cb) { this.onSaveSettings = cb; }
    public void setOnLoadSettings(Runnable cb) { this.onLoadSettings = cb; }
    public void setOnRemoveHiscore(Consumer<String[]> cb) { this.onRemoveHiscore = cb; }
    public void setOnRotateApiKey(Consumer<String> cb) { this.onRotateApiKey = cb; }
    public void setOnStartEvent(Consumer<String[]> cb) { this.onStartEvent = cb; }
    public void setOnCancelEvent(Consumer<String> cb) { this.onCancelEvent = cb; }
    public void setOnLoadEvents(Runnable cb) { this.onLoadEvents = cb; }

    /**
     * Render the event calendar. Rows: {id, status, displayName, windowText}.
     * Active rows get an End button, scheduled rows a Cancel button.
     */
    public void setEventsList(List<String[]> rows)
    {
        SwingUtilities.invokeLater(() -> {
            eventsListPanel.removeAll();
            if (rows.isEmpty())
            {
                JLabel none = new JLabel("No running or scheduled events.");
                none.setFont(SMALL_ITALIC);
                none.setForeground(new Color(150, 150, 150));
                none.setAlignmentX(Component.LEFT_ALIGNMENT);
                eventsListPanel.add(none);
            }
            for (String[] row : rows)
            {
                final String id = row[0];
                String status = row[1];
                boolean live = "active".equals(status);
                Color chipColor = live ? new Color(76, 175, 80) : new Color(100, 149, 237);

                JPanel card = new JPanel(new BorderLayout(4, 0));
                card.setBackground(new Color(35, 35, 35));
                card.setAlignmentX(Component.LEFT_ALIGNMENT);
                card.setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createMatteBorder(0, 3, 0, 0, chipColor),
                    new EmptyBorder(4, 6, 4, 4)));

                JPanel text = new JPanel();
                text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
                text.setBackground(new Color(35, 35, 35));
                String glyph = row.length > 4 && row[4] != null ? row[4] : "";
                JLabel name = new JLabel("<html><b>" + (live ? "LIVE" : "SCHEDULED") + "</b> \u00b7 " + glyph + row[2] + "</html>");
                name.setFont(SMALL_FONT);
                name.setForeground(chipColor);
                text.add(name);
                JLabel window = new JLabel("<html>" + row[3] + "</html>");
                window.setFont(SMALL_ITALIC);
                window.setForeground(new Color(150, 150, 150));
                text.add(window);
                card.add(text, BorderLayout.CENTER);

                JButton act = createButton(live ? "End" : "Cancel");
                act.addActionListener(e -> {
                    if (confirmAction((live ? "End" : "Cancel") + " \"" + row[2] + "\"?"))
                    {
                        if (onCancelEvent != null) onCancelEvent.accept(id);
                    }
                });
                JPanel btnWrap = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
                btnWrap.setBackground(new Color(35, 35, 35));
                btnWrap.add(act);
                card.add(btnWrap, BorderLayout.EAST);

                card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height + 4));
                eventsListPanel.add(card);
                eventsListPanel.add(Box.createVerticalStrut(3));
            }
            eventsListPanel.revalidate();
            eventsListPanel.repaint();
        });
    }
    public void setOnSyncRoster(Runnable cb) { this.onSyncRoster = cb; }
    public void setOnCreateAnnouncement(Consumer<Object[]> cb) { this.onCreateAnnouncement = cb; }
    public void setOnEditAnnouncement(Consumer<String[]> cb) { this.onEditAnnouncement = cb; }
    public void setOnTogglePinAnnouncement(Consumer<Object[]> cb) { this.onTogglePinAnnouncement = cb; }
    public void setOnDeleteAnnouncement(Consumer<String> cb) { this.onDeleteAnnouncement = cb; }

    /** Populate the admin announcements list with edit/pin/delete controls per row. */
    public void setAnnouncementsList(List<PlatformApiService.Announcement> items)
    {
        SwingUtilities.invokeLater(() -> {
            List<PlatformApiService.Announcement> list = items != null ? items : new ArrayList<>();
            announcementsListPanel.removeAll();
            if (list.isEmpty())
            {
                JLabel none = new JLabel("No announcements yet");
                none.setFont(SMALL_ITALIC);
                none.setForeground(new Color(120, 120, 120));
                none.setAlignmentX(Component.LEFT_ALIGNMENT);
                announcementsListPanel.add(none);
            }
            else
            {
                for (PlatformApiService.Announcement a : list)
                {
                    announcementsListPanel.add(buildAnnouncementRow(a));
                    announcementsListPanel.add(Box.createVerticalStrut(2));
                }
            }
            announcementsListPanel.revalidate();
            announcementsListPanel.repaint();
        });
    }

    private JPanel buildAnnouncementRow(PlatformApiService.Announcement a)
    {
        JPanel row = new JPanel(new BorderLayout(4, 0));
        row.setBackground(new Color(35, 35, 35));
        row.setBorder(new EmptyBorder(3, 5, 3, 5));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 48));

        String pin = a.pinned ? "📌 " : ""; // pushpin
        JLabel text = new JLabel("<html>" + pin + escapeHtml(a.message) + "</html>");
        text.setFont(SMALL_FONT);
        text.setForeground(new Color(200, 200, 200));
        row.add(text, BorderLayout.CENTER);

        JPanel btns = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        btns.setBackground(new Color(35, 35, 35));

        JButton edit = miniButton("Edit");
        edit.addActionListener(e -> {
            Object updated = JOptionPane.showInputDialog(this, "Edit announcement:", "Edit Announcement",
                JOptionPane.PLAIN_MESSAGE, null, null, a.message);
            if (updated != null && !updated.toString().trim().isEmpty() && onEditAnnouncement != null)
            {
                onEditAnnouncement.accept(new String[]{a.id, updated.toString().trim()});
            }
        });

        JButton pin2 = miniButton(a.pinned ? "Unpin" : "Pin");
        pin2.addActionListener(e -> {
            if (onTogglePinAnnouncement != null) onTogglePinAnnouncement.accept(new Object[]{a.id, !a.pinned});
        });

        JButton del = miniButton("Del");
        del.addActionListener(e -> {
            if (confirmAction("Delete this announcement?") && onDeleteAnnouncement != null) onDeleteAnnouncement.accept(a.id);
        });

        btns.add(edit);
        btns.add(pin2);
        btns.add(del);
        row.add(btns, BorderLayout.EAST);
        return row;
    }

    private JButton miniButton(String text)
    {
        JButton b = new JButton(text);
        b.setFont(new Font("Segoe UI", Font.PLAIN, 10));
        b.setMargin(new Insets(1, 4, 1, 4));
        b.setFocusPainted(false);
        return b;
    }

    private static String escapeHtml(String s)
    {
        if (s == null) return "";
        return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    public void setNewBoardCode(String code)
    {
        SwingUtilities.invokeLater(() -> newBoardCodeLabel.setText("New code: " + code));
    }

    /** Legacy hook (config refresh calls this) — the calendar list is the display now. */
    public void setActiveEvent(String type, String displayName, String endTime)
    {
        if (onLoadEvents != null) onLoadEvents.run();
    }

    private void populateMetricBox()
    {
        eventMetricBox.removeAllItems();
        String selected = (String) eventTypeBox.getSelectedItem();
        if (selected == null) return;
        String type = EventMetrics.typeFromLabel(selected);
        if (type == null) return;
        switch (type)
        {
            case "boss":
                for (String name : EventMetrics.getBossDisplayNames()) eventMetricBox.addItem(name);
                break;
            case "skill":
                for (String name : EventMetrics.getSkillDisplayNames()) eventMetricBox.addItem(name);
                break;
            case "gamer":
                for (String name : EventMetrics.getActivityDisplayNames()) eventMetricBox.addItem(name);
                break;
            case "clue":
                for (String name : EventMetrics.getClueDisplayNames()) eventMetricBox.addItem(name);
                break;
        }
    }

    // ── Helpers ──

    private boolean confirmAction(String message)
    {
        return JOptionPane.showConfirmDialog(this, message, "Confirm",
            JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION;
    }

    private JLabel createSectionTitle(String text)
    {
        JLabel label = new JLabel(text);
        label.setFont(SECTION_FONT);
        label.setForeground(new Color(255, 180, 100));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }

    private JLabel createFieldLabel(String text)
    {
        JLabel label = new JLabel(text);
        label.setFont(SMALL_FONT);
        label.setForeground(new Color(160, 160, 160));
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        label.setBorder(new EmptyBorder(0, 0, 2, 0));
        return label;
    }

    private JPanel createLabeledField(String labelText, JComponent field)
    {
        JPanel panel = new JPanel(new BorderLayout(4, 0));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));

        JLabel label = new JLabel(labelText);
        label.setFont(SMALL_FONT);
        label.setForeground(new Color(200, 200, 200));
        label.setPreferredSize(new Dimension(60, 20));

        panel.add(label, BorderLayout.WEST);
        panel.add(field, BorderLayout.CENTER);
        return panel;
    }

    private JButton createButton(String text)
    {
        JButton btn = new JButton(text);
        btn.setFont(SMALL_FONT);
        btn.setMargin(new Insets(2, 6, 2, 6));
        btn.setFocusPainted(false);
        return btn;
    }

    private JSeparator createSeparator()
    {
        JSeparator sep = new JSeparator();
        sep.setForeground(new Color(60, 60, 60));
        sep.setAlignmentX(Component.LEFT_ALIGNMENT);
        sep.setMaximumSize(new Dimension(Integer.MAX_VALUE, 2));
        return sep;
    }
}

package com.droplogger;

import com.google.gson.*;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.TimeUnit;

@Slf4j
@Singleton
public class AdminService
{
    private static final MediaType JSON_TYPE = MediaType.parse("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson gson;

    @Inject
    public AdminService(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient.newBuilder()
            .callTimeout(60, TimeUnit.SECONDS)
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            // Every URL this plugin calls is the one hardcoded address. A redirect is a URL chosen
            // by the response rather than by us, so following one would take it somewhere that is
            // neither hardcoded nor entered by the user. Declined, here and on every other client.
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
        this.gson = gson;
    }

    /**
     * Start a weekly event via the platform API.
     * POST /admin/{slug}/events
     */
    public String startEventPlatform(String baseUrl, String apiKey, String slug,
                                      String eventType, String metric, String displayName,
                                      String startAtIso, String endAtIso) throws IOException
    {
        JsonObject payload = new JsonObject();
        payload.addProperty("type", eventType);
        payload.addProperty("metric", metric);
        payload.addProperty("displayName", displayName);
        if (startAtIso != null) payload.addProperty("startAt", startAtIso);
        if (endAtIso != null) payload.addProperty("endAt", endAtIso);

        RequestBody body = RequestBody.create(JSON_TYPE, gson.toJson(payload));
        Request request = new Request.Builder()
            .url(baseUrl + "/admin/" + slug + "/events")
            .header("Authorization", "Bearer " + apiKey)
            .post(body)
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                // Surface the server's reason (e.g. the event-overlap rejection) instead of a bare code.
                String detail = null;
                try
                {
                    JsonObject err = gson.fromJson(response.body() != null ? response.body().string() : null, JsonObject.class);
                    if (err != null && err.has("error")) detail = err.get("error").getAsString();
                }
                catch (Exception ignored) { }
                throw new IOException(detail != null ? detail : "Platform API returned status: " + response.code());
            }
            return "Event started";
        }
    }

    /** Running + scheduled events for the admin calendar. GET /clans/{slug}/events */
    public java.util.List<JsonObject> fetchEventsList(String baseUrl, String apiKey, String slug) throws IOException
    {
        Request request = new Request.Builder()
            .url(baseUrl + "/clans/" + slug + "/events?limit=8")
            .header("Authorization", "Bearer " + apiKey)
            .get()
            .build();
        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("Platform API returned status: " + response.code());
            }
            JsonObject root = gson.fromJson(response.body().string(), JsonObject.class);
            java.util.List<JsonObject> out = new java.util.ArrayList<>();
            if (root != null && root.has("events"))
            {
                for (com.google.gson.JsonElement el : root.getAsJsonArray("events"))
                {
                    out.add(el.getAsJsonObject());
                }
            }
            return out;
        }
    }

    /**
     * End a weekly event via the platform API.
     * POST /admin/{slug}/events/{id}/end
     */
    public String endEventPlatform(String baseUrl, String apiKey, String slug,
                                    String eventId) throws IOException
    {
        Request request = new Request.Builder()
            .url(baseUrl + "/admin/" + slug + "/events/" + eventId + "/end")
            .header("Authorization", "Bearer " + apiKey)
            .post(RequestBody.create(JSON_TYPE, "{}"))
            .build();

        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful())
            {
                throw new IOException("Platform API returned status: " + response.code());
            }
            return "Event ended";
        }
    }
}

package com.droplogger;

import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;

import javax.swing.JComponent;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;

/**
 * Renders a rows x cols bingo board. Kept independent of any particular data source: it takes
 * rows, cols and a List&lt;BingoTile&gt; (plus the two game-icon managers), so the same renderer
 * draws today's sample data and tomorrow's real server data unchanged.
 *
 * Each tile shows its sprite/item icon with gold filling up from the bottom in proportion to
 * points/threshold, like a glass filling; at 100% the tile turns fully gold and gets a bright gold
 * border. Points read out underneath as "12/30". A tile whose icon could not be resolved (an
 * item-less tile, or a Wise Old Man metric with no matching sprite) draws its tile code in the
 * middle instead, so it still reads as a real tile.
 *
 * Every kind of tile renders identically here: a kc/xp tile's points arrive the same way a drop
 * tile's do, so the fill needs no special case.
 */
public class BingoBoardPanel extends JPanel
{
    /**
     * Places tiles into a rows x cols grid. row/col from the server are ONE-based: a board is
     * authored in a spreadsheet whose top-left tile is row 1, col 1, and the server's own
     * tileWithinGrid rejects anything below 1. Treating them as zero-based left the top-left cell
     * blank and silently dropped the whole last row and column off the board (the dev preview hid
     * it by using zero-based sample data). Anything outside the grid is ignored rather than
     * throwing: a host who shrinks a board mid-event leaves tiles behind.
     *
     * Package-private and pure so the indexing can be tested without building a panel.
     */
    static BingoTile[][] layOutForTest(java.util.List<BingoTile> tiles, int rows, int cols)
    {
        BingoTile[][] grid = new BingoTile[rows][cols];
        if (tiles == null) return grid;
        for (BingoTile t : tiles)
        {
            if (t != null && t.row >= 1 && t.row <= rows && t.col >= 1 && t.col <= cols)
            {
                grid[t.row - 1][t.col - 1] = t;
            }
        }
        return grid;
    }

    private static final Color GOLD = new Color(212, 175, 55);
    private static final Color GOLD_FILL = new Color(212, 175, 55, 195); // translucent so the icon stays readable
    private static final Color BRIGHT_GOLD_BORDER = new Color(255, 215, 0);
    private static final Font POINTS_FONT = new Font("Segoe UI", Font.PLAIN, 9);
    private static final Font CODE_FONT = new Font("Segoe UI", Font.BOLD, 11);

    private static final int USABLE_WIDTH = 225; // RuneLite side panel usable width
    private static final int GAP = 3;

    public BingoBoardPanel(int rows, int cols, List<BingoTile> tiles, ItemManager itemManager, SpriteManager spriteManager)
    {
        this(rows, cols, tiles, itemManager, spriteManager, null);
    }

    /**
     * Same as the three-manager constructor, plus an optional onTileClick callback (null = no click
     * behaviour, identical to the original constructor). Invoked on the EDT with the clicked tile;
     * a click on an empty grid cell (no tile mapped to that row/col) is a no-op.
     */
    public BingoBoardPanel(int rowsIn, int colsIn, List<BingoTile> tiles, ItemManager itemManager, SpriteManager spriteManager,
        java.util.function.Consumer<BingoTile> onTileClick)
    {
        // GridLayout throws when rows and cols are both zero, which a payload with a board but no
        // grid size would otherwise produce; one empty cell is a harmless board, an exception is not.
        int rows = Math.max(1, rowsIn);
        int cols = Math.max(1, colsIn);
        setLayout(new GridLayout(rows, cols, GAP, GAP));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setOpaque(true);

        int tileSize = Math.max(16, (USABLE_WIDTH - GAP * (cols - 1)) / Math.max(1, cols));
        int width = tileSize * cols + GAP * (cols - 1);
        int height = tileSize * rows + GAP * (rows - 1);
        Dimension size = new Dimension(width, height);
        setPreferredSize(size);
        setMaximumSize(size);
        setAlignmentX(Component.LEFT_ALIGNMENT);

        BingoTile[][] grid = layOutForTest(tiles, rows, cols);

        // GridLayout adds row-major, matching this loop order.
        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                add(new TileComponent(grid[r][c], tileSize, itemManager, spriteManager, onTileClick));
            }
        }
    }

    /**
     * One tile's custom-painted cell: dark background, gold fill rising from the bottom, a
     * centred icon, the points readout, and (at 100%) a bright gold border. The icon is cached on
     * this component (one per tile) and loaded once; both SpriteManager and ItemManager callbacks
     * can land off the EDT, so every store-and-repaint hops through SwingUtilities.invokeLater. A
     * missing or failed icon lookup just leaves the tile without one, never throws.
     */
    private static final class TileComponent extends JComponent
    {
        private final BingoTile tile;
        private volatile BufferedImage icon;

        TileComponent(BingoTile tile, int size, ItemManager itemManager, SpriteManager spriteManager,
            java.util.function.Consumer<BingoTile> onTileClick)
        {
            this.tile = tile;
            setPreferredSize(new Dimension(size, size));
            setOpaque(false);
            if (tile != null)
            {
                // A kc/xp tile says so, since "30/50 pts" alone would not explain where its points
                // come from (Wise Old Man gains, not drops).
                String kindLabel = tile.kindLabel();
                String heading = kindLabel != null ? tile.name + " (" + kindLabel + ")" : tile.name;
                setToolTipText(heading + ": " + BingoTiles.formatPoints(tile.points, tile.threshold) + " pts");
                loadIcon(itemManager, spriteManager);
                if (onTileClick != null)
                {
                    setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
                    addMouseListener(new java.awt.event.MouseAdapter()
                    {
                        @Override public void mouseClicked(java.awt.event.MouseEvent e) { onTileClick.accept(tile); }
                    });
                }
            }
        }

        private void loadIcon(ItemManager itemManager, SpriteManager spriteManager)
        {
            try
            {
                if (tile.isBoss())
                {
                    if (spriteManager == null)
                    {
                        return;
                    }
                    // Already resolved when the tile was built (a kc/xp tile's sprite can be a skill,
                    // which the boss-only lookup would miss).
                    int spriteId = tile.spriteId;
                    if (spriteId < 0)
                    {
                        return; // no matching sprite: tile just renders its code instead of an icon
                    }
                    spriteManager.getSpriteAsync(spriteId, 0, img -> SwingUtilities.invokeLater(() ->
                    {
                        icon = img;
                        repaint();
                    }));
                }
                else if (itemManager != null && tile.itemId > 0)
                {
                    AsyncBufferedImage img = itemManager.getImage(tile.itemId);
                    icon = img;
                    img.onLoaded(() -> SwingUtilities.invokeLater(this::repaint));
                }
            }
            catch (Exception e)
            {
                // Never let an icon lookup failure take the board down with it.
                icon = null;
            }
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            super.paintComponent(g);
            if (tile == null)
            {
                return; // no tile mapped to this row/col: leave the cell blank
            }

            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            int w = getWidth();
            int h = getHeight();
            double frac = BingoTiles.fillFraction(tile.points, tile.threshold);
            // The server's own verdict wins when it says complete: a tile with a threshold of zero is
            // complete from the start with no points at all, which points/threshold cannot express.
            boolean full = tile.complete || frac >= 1.0;
            if (full) frac = 1.0;

            g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
            g2.fillRect(0, 0, w, h);

            int fillHeight = (int) Math.round(h * frac);
            if (fillHeight > 0)
            {
                g2.setColor(full ? GOLD : GOLD_FILL);
                g2.fillRect(0, h - fillHeight, w, fillHeight);
            }

            BufferedImage img = icon;
            if (img != null)
            {
                int iw = img.getWidth();
                int ih = img.getHeight();
                g2.drawImage(img, (w - iw) / 2, (h - ih) / 2 - 3, null);
            }
            else if (tile.code != null && !tile.code.isEmpty())
            {
                // No icon resolved (an item-less tile, or a Wise Old Man metric with no sprite): draw
                // the tile code so the cell still reads as a real tile rather than an empty square.
                g2.setFont(CODE_FONT);
                FontMetrics cfm = g2.getFontMetrics();
                int cx = (w - cfm.stringWidth(tile.code)) / 2;
                int cy = (h - cfm.getHeight()) / 2 + cfm.getAscent() - 3;
                g2.setColor(full ? new Color(70, 55, 10) : new Color(140, 140, 140));
                g2.drawString(tile.code, cx, cy);
            }

            String text = BingoTiles.formatPoints(tile.points, tile.threshold);
            g2.setFont(POINTS_FONT);
            FontMetrics fm = g2.getFontMetrics();
            int tx = (w - fm.stringWidth(text)) / 2;
            int ty = h - 3;
            g2.setColor(Color.BLACK);
            g2.drawString(text, tx + 1, ty + 1);
            g2.setColor(Color.WHITE);
            g2.drawString(text, tx, ty);

            if (full)
            {
                g2.setColor(BRIGHT_GOLD_BORDER);
                g2.setStroke(new BasicStroke(2f));
                g2.drawRect(1, 1, w - 3, h - 3);
            }

            g2.dispose();
        }
    }
}

package com.droplogger;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Pure helpers for the plugin's bingo team-view card: turning a {@link PlatformApiService.BingoCard}
 * into the things the panel renders (which team is "yours", one team's board as
 * List&lt;BingoTile&gt;, and the points/tiles/rank/gap status line). No Swing, no network, no game
 * state, so these are plain JUnit-testable, matching {@link BingoTiles}.
 */
public final class BingoTeamView
{
    private BingoTeamView()
    {
    }

    /** Same normalization as ClanManagementPlugin's private normalizeName, duplicated here so RSN
     *  matching stays testable without instantiating the (RuneLite-injected) plugin class. */
    public static String normalizeName(String s)
    {
        if (s == null) return "";
        return s.toLowerCase(Locale.ROOT).replace('_', ' ').replace('-', ' ').replaceAll(" +", " ").trim();
    }

    public static boolean isSamePlayer(String a, String b)
    {
        String na = normalizeName(a);
        return !na.isEmpty() && na.equals(normalizeName(b));
    }

    /**
     * The team whose roster contains localPlayerName (normalized match), or null when it is on no
     * team, the card has no teams, or localPlayerName is blank. Ties (a name on two rosters, which
     * should not happen server-side) resolve to the first team listed.
     */
    public static String findOwnTeamId(PlatformApiService.BingoCard card, String localPlayerName)
    {
        if (card == null || card.teams == null || localPlayerName == null) return null;
        String target = normalizeName(localPlayerName);
        if (target.isEmpty()) return null;
        for (PlatformApiService.BingoTeam team : card.teams)
        {
            if (team == null || team.members == null) continue;
            for (String member : team.members)
            {
                if (normalizeName(member).equals(target)) return team.teamId;
            }
        }
        return null;
    }

    /** This card's total tile count, from the board definition (0 when there is no board yet). */
    public static int totalTiles(PlatformApiService.BingoCard card)
    {
        if (card == null || card.board == null || card.board.tiles == null) return 0;
        return card.board.tiles.size();
    }

    /** The team-view entry (points/tilesComplete/rank/gap/roster/recentDrops) for one team, or null
     *  when teams haven't been loaded yet / teamId doesn't match anything. This reads card.teams,
     *  NOT card.standings: the real API puts the rich per-team fields on teams[], while standings[]
     *  is only the plain leaderboard (teamId/name/color/points/tilesComplete/rank). */
    public static PlatformApiService.BingoTeam teamForTeamId(PlatformApiService.BingoCard card, String teamId)
    {
        if (card == null || card.teams == null || teamId == null) return null;
        for (PlatformApiService.BingoTeam t : card.teams)
        {
            if (t != null && teamId.equals(t.teamId)) return t;
        }
        return null;
    }

    /** "1st", "2nd", "3rd", "4th", ... "11th"/"12th"/"13th" special-cased. rank <= 0 renders as-is. */
    public static String rankOrdinal(int rank)
    {
        if (rank <= 0) return String.valueOf(rank);
        int mod100 = rank % 100;
        if (mod100 >= 11 && mod100 <= 13) return rank + "th";
        switch (rank % 10)
        {
            case 1: return rank + "st";
            case 2: return rank + "nd";
            case 3: return rank + "rd";
            default: return rank + "th";
        }
    }

    /**
     * The points / tiles / rank / gap status line for one team, e.g.
     * "128 pts | 9/25 tiles | Rank 1 of 4 | Leading by 20 pts" (rank 1, a lead known) or
     * "108 pts | 8/25 tiles | Rank 2 of 4 | 20 pts behind 1st" (any other rank, a gap known).
     * Trailing clauses are omitted rather than guessed when the corresponding gap is null.
     */
    public static String formatTeamStatusLine(double points, int tilesComplete, int totalTiles, int rank, int teamCount,
        PlatformApiService.BingoGap gapToAbove, PlatformApiService.BingoGap leadOverBelow)
    {
        StringBuilder sb = new StringBuilder();
        sb.append(formatNumber(points)).append(points == 1 ? " pt" : " pts");
        sb.append(" | ").append(tilesComplete).append("/").append(totalTiles).append(" tiles");
        if (rank > 0 && teamCount > 0)
        {
            sb.append(" | Rank ").append(rank).append(" of ").append(teamCount);
        }
        if (rank == 1)
        {
            if (leadOverBelow != null)
            {
                sb.append(" | Leading by ").append(formatNumber(leadOverBelow.points))
                  .append(leadOverBelow.points == 1 ? " pt" : " pts");
            }
        }
        else if (gapToAbove != null)
        {
            sb.append(" | ").append(formatNumber(gapToAbove.points)).append(gapToAbove.points == 1 ? " pt" : " pts")
              .append(" behind ").append(rank > 1 ? rankOrdinal(rank - 1) : "1st");
        }
        return sb.toString();
    }

    private static String formatNumber(double v)
    {
        if (v == Math.rint(v) && !Double.isInfinite(v)) return String.valueOf((long) v);
        return String.format(Locale.US, "%.1f", v);
    }

    /**
     * Resolve one static board tile plus that team's progress into the renderer's {@link BingoTile}.
     *
     * Progress is the same for every kind of tile: points come from progress[teamId][code], so the
     * board's gold fill works on a kc/xp tile exactly as it does on a drop tile. A kc/xp tile whose
     * points have never been computed (no successful Wise Old Man sync yet, or a WOM outage freezing
     * them) simply reads as zero points, which renders as an empty tile, not an error.
     *
     * Only the icon differs by kind:
     *  - drop tile: the icon string first as a boss/activity name (via {@link BingoTiles#bossSpriteId}),
     *    else as a bare item id, else as an item name matched against the tile's own items, else the
     *    tile's first item, else no icon.
     *  - kc/xp tile: the icon string first (a host may still set one explicitly), then womMetric
     *    resolved through {@link BingoTiles#metricSpriteId}, which also matches skills, since an xp
     *    tile's metric is a skill. It NEVER falls back to an item: a kc/xp tile has no items, and
     *    reaching for one would be the "broken drop tile" rendering this branch exists to avoid.
     *
     * An unresolved icon means itemId 0, which BingoBoardPanel renders as a cell labelled with the
     * tile code rather than a blank square, so the tile still reads as a real tile.
     */
    public static BingoTile resolveTile(PlatformApiService.BingoBoardTile t, PlatformApiService.BingoTileProgress progress)
    {
        double points = progress != null ? progress.points : 0;
        boolean complete = progress != null && progress.complete;
        double threshold = t.threshold > 0 ? t.threshold : t.max;
        String kind = t.kind == null || t.kind.isEmpty() ? BingoTile.KIND_DROP : t.kind;
        boolean wom = t.isWomTile();

        String icon = t.icon == null ? "" : t.icon.trim();
        if (!icon.isEmpty())
        {
            // A kc/xp tile's explicit icon may name a skill ("Woodcutting"), so it uses the wider
            // metric lookup; a drop tile keeps the boss/activity-only lookup it has always used.
            int spriteId = wom ? BingoTiles.metricSpriteId(icon) : BingoTiles.bossSpriteId(icon);
            if (spriteId >= 0)
            {
                return BingoTile.sprite(t.code, t.name, t.row, t.col, points, threshold, icon, spriteId, kind, complete);
            }
            try
            {
                int id = Integer.parseInt(icon);
                return BingoTile.item(t.code, t.name, t.row, t.col, points, threshold, id, kind, complete);
            }
            catch (NumberFormatException notAnId)
            {
                if (t.items != null)
                {
                    for (PlatformApiService.BingoItem item : t.items)
                    {
                        if (item.itemName != null && item.itemName.equalsIgnoreCase(icon))
                        {
                            return BingoTile.item(t.code, t.name, t.row, t.col, points, threshold, item.itemId, kind, complete);
                        }
                    }
                }
            }
        }
        if (wom)
        {
            int spriteId = BingoTiles.metricSpriteId(t.womMetric);
            if (spriteId >= 0)
            {
                return BingoTile.sprite(t.code, t.name, t.row, t.col, points, threshold, t.womMetric, spriteId, kind, complete);
            }
            return BingoTile.item(t.code, t.name, t.row, t.col, points, threshold, 0, kind, complete);
        }
        if (t.items != null && !t.items.isEmpty())
        {
            return BingoTile.item(t.code, t.name, t.row, t.col, points, threshold, t.items.get(0).itemId, kind, complete);
        }
        return BingoTile.item(t.code, t.name, t.row, t.col, points, threshold, 0, kind, complete);
    }

    /** The selected team's whole board as the renderer's List&lt;BingoTile&gt;. Missing progress for
     *  a tile (team hasn't touched it, or the team has no progress map at all) reads as 0 points. */
    public static List<BingoTile> toBoardTiles(PlatformApiService.BingoCard card, String teamId)
    {
        List<BingoTile> out = new ArrayList<>();
        if (card == null || card.board == null || card.board.tiles == null) return out;
        java.util.Map<String, PlatformApiService.BingoTileProgress> byTile =
            card.progress != null && teamId != null ? card.progress.get(teamId) : null;
        for (PlatformApiService.BingoBoardTile t : card.board.tiles)
        {
            if (t == null) continue;
            PlatformApiService.BingoTileProgress progress = byTile != null ? byTile.get(t.code) : null;
            out.add(resolveTile(t, progress));
        }
        return out;
    }
}

package com.droplogger;

/**
 * Immutable bingo tile: identity, board position, progress, and an icon reference that is EITHER a
 * sprite (a boss/activity/skill icon, already resolved to a sprite id) OR an item id (rendered via
 * ItemManager). Exactly one of the two is set; use the {@link #boss} / {@link #item} /
 * {@link #sprite} factories rather than the constructor directly.
 *
 * kind mirrors the server's tile kind: "drop" (scored from item drops) or "kc"/"xp" (scored from
 * Wise Old Man gains). The renderer treats them identically for progress, since every kind reports
 * its points the same way; kind only changes where the icon comes from and how the tooltip reads.
 *
 * complete is the server's own completion verdict for this team. It is carried separately from
 * points/threshold because a tile with a threshold of zero is complete from the start with no points
 * at all, which points/threshold alone cannot express.
 *
 * Deliberately independent of any data source: {@link BingoBoardPanel} only ever sees a
 * List&lt;BingoTile&gt;, so sample data and real server data feed the same renderer unchanged.
 */
public final class BingoTile
{
    public static final String KIND_DROP = "drop";
    public static final String KIND_KC = "kc";
    public static final String KIND_XP = "xp";

    public final String code; // e.g. "A1"
    public final String name;
    // ONE-based, straight from the server: a board is authored in a spreadsheet whose top-left tile
    // is row 1, col 1, and the server's own tileWithinGrid rejects anything below 1. BingoBoardPanel
    // subtracts one when it places a tile into its grid array.
    public final int row;
    public final int col;
    public final double points;
    public final double threshold;
    public final String bossName; // sprite label (boss/activity/skill name or WOM metric); null when this tile uses an item icon
    public final int spriteId; // resolved sprite id, -1 when none resolved
    public final int itemId; // 0 when this tile uses a sprite icon instead
    public final String kind; // "drop" | "kc" | "xp", never null
    public final boolean complete; // the server's completion verdict for this team

    private BingoTile(String code, String name, int row, int col, double points, double threshold,
        String bossName, int spriteId, int itemId, String kind, boolean complete)
    {
        this.code = code;
        this.name = name;
        this.row = row;
        this.col = col;
        this.points = points;
        this.threshold = threshold;
        this.bossName = bossName;
        this.spriteId = spriteId;
        this.itemId = itemId;
        this.kind = kind == null || kind.isEmpty() ? KIND_DROP : kind;
        this.complete = complete;
    }

    /** Sprite-icon tile whose label is looked up as a boss/activity name. */
    public static BingoTile boss(String code, String name, int row, int col, double points, double threshold,
        String bossName)
    {
        return boss(code, name, row, col, points, threshold, bossName, KIND_DROP, false);
    }

    public static BingoTile boss(String code, String name, int row, int col, double points, double threshold,
        String bossName, String kind, boolean complete)
    {
        return new BingoTile(code, name, row, col, points, threshold, bossName,
            BingoTiles.bossSpriteId(bossName), 0, kind, complete);
    }

    /** Sprite-icon tile with an already-resolved sprite id (used for kc/xp tiles, whose icon comes
     *  from the WOM metric and may be a skill rather than a boss). */
    public static BingoTile sprite(String code, String name, int row, int col, double points, double threshold,
        String label, int spriteId, String kind, boolean complete)
    {
        return new BingoTile(code, name, row, col, points, threshold, label, spriteId, 0, kind, complete);
    }

    public static BingoTile item(String code, String name, int row, int col, double points, double threshold,
        int itemId)
    {
        return item(code, name, row, col, points, threshold, itemId, KIND_DROP, false);
    }

    public static BingoTile item(String code, String name, int row, int col, double points, double threshold,
        int itemId, String kind, boolean complete)
    {
        return new BingoTile(code, name, row, col, points, threshold, null, -1, itemId, kind, complete);
    }

    /** True when this tile draws a sprite rather than an item image. */
    public boolean isBoss()
    {
        return bossName != null;
    }

    /** True for a Wise Old Man scored tile, which has no items and never matches a drop. */
    public boolean isWomTile()
    {
        return KIND_KC.equalsIgnoreCase(kind) || KIND_XP.equalsIgnoreCase(kind);
    }

    /** "KC" / "XP" for a Wise Old Man tile, else null: a short suffix for the tile tooltip. */
    public String kindLabel()
    {
        if (KIND_KC.equalsIgnoreCase(kind)) return "KC";
        if (KIND_XP.equalsIgnoreCase(kind)) return "XP";
        return null;
    }
}

package com.droplogger;

import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

import java.util.Locale;

/**
 * Pure helpers for the bingo board renderer: fill fraction, boss-name to sprite lookup, and the
 * "12/30" points readout. No Swing, no network, no game state, so these are plain JUnit-testable.
 */
public final class BingoTiles
{
    private BingoTiles()
    {
    }

    /**
     * points/threshold, clamped to [0, 1]. A threshold that is zero or negative is treated as
     * "already there": a tile with any positive points is full, one with none is empty. Negative
     * points never count against the tile, so they always read as empty.
     */
    public static double fillFraction(double points, double threshold)
    {
        if (threshold <= 0)
        {
            return points > 0 ? 1.0 : 0.0;
        }
        if (points <= 0)
        {
            return 0.0;
        }
        double frac = points / threshold;
        if (frac > 1.0) return 1.0;
        return frac;
    }

    /**
     * Finds the HiscoreSkill entry (boss or boss-adjacent activity, e.g. a raid) whose name
     * matches bossName once both are normalized to lowercase letters/digits only, so "Kree'arra",
     * "kreearra" and "Kree Arra" all match the same entry. Returns that entry's sprite id, or -1
     * when nothing matches.
     */
    public static int bossSpriteId(String bossName)
    {
        return spriteIdFor(bossName, false);
    }

    /**
     * Sprite for a Wise Old Man metric as carried by a kc/xp tile (womMetric), e.g. "vorkath",
     * "chambers_of_xeric" or "woodcutting". Same normalization as {@link #bossSpriteId}, so WOM's
     * underscore slugs line up with RuneLite's display names, but skills are matched too: an xp
     * tile's metric is a skill, not a boss. Returns -1 when nothing matches (an untracked or
     * aggregate metric such as "ehb"), which renders as a tile with no icon rather than a broken one.
     */
    public static int metricSpriteId(String metric)
    {
        return spriteIdFor(metric, true);
    }

    private static int spriteIdFor(String name, boolean includeSkills)
    {
        String target = normalize(name);
        if (target.isEmpty())
        {
            return -1;
        }
        for (HiscoreSkill skill : HiscoreSkill.values())
        {
            HiscoreSkillType type = skill.getType();
            boolean eligible = type == HiscoreSkillType.BOSS || type == HiscoreSkillType.ACTIVITY
                || (includeSkills && type == HiscoreSkillType.SKILL);
            if (!eligible)
            {
                continue;
            }
            if (normalize(skill.getName()).equals(target))
            {
                return skill.getSpriteId();
            }
        }
        return -1;
    }

    private static String normalize(String s)
    {
        if (s == null)
        {
            return "";
        }
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++)
        {
            char c = s.charAt(i);
            if (Character.isLetterOrDigit(c))
            {
                sb.append(Character.toLowerCase(c));
            }
        }
        return sb.toString();
    }

    /** "12/30" for whole numbers, "7.5/30" when either side has a fractional part. */
    public static String formatPoints(double points, double threshold)
    {
        return formatNumber(points) + "/" + formatNumber(threshold);
    }

    private static String formatNumber(double v)
    {
        if (v == Math.rint(v) && !Double.isInfinite(v))
        {
            return String.valueOf((long) v);
        }
        return String.format(Locale.US, "%.1f", v);
    }
}

package com.droplogger;

import com.google.gson.*;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

/**
 * Reads clan board data from the clan-platform REST API.
 * Endpoints: {base}/clans/{slug}/{leaderboard,drops,whitelist}, Bearer-authed.
 * Return shapes are kept identical to the legacy version so ClanPanel consumes them unchanged.
 */
@Slf4j
@Singleton
public class BoardDataService
{
    private final OkHttpClient httpClient;
    private final Gson gson;

    @Inject
    public BoardDataService(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient.newBuilder()
            .callTimeout(60, TimeUnit.SECONDS)
            .connectTimeout(30, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            // Every URL this plugin calls is the one hardcoded address. A redirect is a URL chosen
            // by the response rather than by us, so following one would take it somewhere that is
            // neither hardcoded nor entered by the user. Declined, here and on every other client.
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
        this.gson = gson;
    }

    /** Live draft state for the Event tab: teams, pool, picks. Null when no draft exists. */
    public JsonObject fetchDraft(String base, String slug, String key) throws IOException
    {
        JsonObject root = get(base, slug, key, "draft", null);
        if (root == null || !root.has("draft") || root.get("draft").isJsonNull())
        {
            return null;
        }
        return root.getAsJsonObject("draft");
    }

    /** GET {base}/clans/{slug}/{path}?query with Bearer auth. Returns parsed object, or null on failure. */
    private JsonObject get(String base, String slug, String key, String path, Map<String, String> query) throws IOException
    {
        if (base == null || base.isEmpty() || slug == null || slug.isEmpty())
        {
            return null;
        }
        HttpUrl parsed = HttpUrl.parse(base);
        if (parsed == null)
        {
            return null;
        }
        HttpUrl.Builder b = parsed.newBuilder().addPathSegment("clans").addPathSegment(slug);
        for (String seg : path.split("/"))
        {
            if (!seg.isEmpty()) b.addPathSegment(seg);
        }
        if (query != null)
        {
            for (Map.Entry<String, String> e : query.entrySet()) b.addQueryParameter(e.getKey(), e.getValue());
        }
        Request request = new Request.Builder().url(b.build())
            .header("Authorization", "Bearer " + (key != null ? key : ""))
            .get().build();
        try (Response response = httpClient.newCall(request).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException(path + " returned status " + response.code());
            }
            JsonElement el = new JsonParser().parse(response.body().string());
            return el.isJsonObject() ? el.getAsJsonObject() : null;
        }
    }

    private static String str(JsonObject o, String k)
    {
        return o.has(k) && !o.get(k).isJsonNull() ? o.get(k).getAsString() : "";
    }

    /**
     * Drops leaderboard ranked by points; merges value + drop count per member.
     * period: "monthly" | "yearly" | "all". Keys per row: rank, rsn, points, value, drops.
     */
    public List<Map<String, Object>> fetchLeaderboard(String base, String slug, String key, String period) throws IOException
    {
        String p = "monthly".equals(period) ? "month" : "yearly".equals(period) ? "year" : "all";

        Map<String, double[]> byRsn = new LinkedHashMap<>(); // rsn -> [points, value, drops]
        Map<String, String> typeByRsn = new LinkedHashMap<>(); // rsn -> account type (for the game-mode filter)
        mergeBoard(base, slug, key, "points", p, byRsn, 0, typeByRsn);
        mergeBoard(base, slug, key, "value", p, byRsn, 1, typeByRsn);
        mergeBoard(base, slug, key, "count", p, byRsn, 2, typeByRsn);

        List<Map<String, Object>> players = new ArrayList<>();
        for (Map.Entry<String, double[]> e : byRsn.entrySet())
        {
            Map<String, Object> player = new LinkedHashMap<>();
            player.put("rsn", e.getKey());
            player.put("points", e.getValue()[0]);           // keep decimals; the panel formats to 1dp
            player.put("value", (long) e.getValue()[1]);
            player.put("drops", (int) e.getValue()[2]);
            player.put("accountType", typeByRsn.get(e.getKey())); // null until the API carries it
            players.add(player);
        }
        players.sort((a, b) -> Double.compare(((Number) b.get("points")).doubleValue(), ((Number) a.get("points")).doubleValue()));
        int rank = 1;
        for (Map<String, Object> player : players) player.put("rank", rank++);
        return players;
    }

    /** Format clan points for display: up to 1 decimal, drop a trailing ".0" (68.2 -> "68.2", 68.0 -> "68"). */
    private static String fmtPts(double p)
    {
        return p == Math.rint(p) ? String.valueOf((long) p) : String.format("%.1f", p);
    }

    private void mergeBoard(String base, String slug, String key, String board, String period,
                            Map<String, double[]> byRsn, int idx, Map<String, String> typeByRsn) throws IOException
    {
        Map<String, String> q = new LinkedHashMap<>();
        q.put("board", board);
        q.put("period", period);
        q.put("limit", "100");
        JsonObject root = get(base, slug, key, "/leaderboard", q);
        if (root == null || !root.has("entries")) return;
        for (JsonElement el : root.getAsJsonArray("entries"))
        {
            JsonObject e = el.getAsJsonObject();
            String rsn = str(e, "rsn");
            double v = e.has("value") ? e.get("value").getAsDouble() : 0.0;
            byRsn.computeIfAbsent(rsn, k -> new double[3])[idx] = v;
            if (e.has("accountType") && !e.get("accountType").isJsonNull())
            {
                typeByRsn.putIfAbsent(rsn, e.get("accountType").getAsString());
            }
        }
    }

    /** GET /drops?limit=N → recent drops. Keys: player, item, value, monster, points, timestamp. */
    public List<Map<String, Object>> fetchRecentDrops(String base, String slug, String key, int limit) throws IOException
    {
        Map<String, String> q = new LinkedHashMap<>();
        q.put("limit", String.valueOf(limit));
        return mapDrops(get(base, slug, key, "/drops", q), true);
    }

    /** GET /drops?player=RSN → a player's drops. Keys: item, value, monster, kc, points, timestamp. */
    public List<Map<String, Object>> fetchPlayerDrops(String base, String slug, String key, String rsn) throws IOException
    {
        Map<String, String> q = new LinkedHashMap<>();
        q.put("player", rsn);
        q.put("limit", "100");
        return mapDrops(get(base, slug, key, "/drops", q), false);
    }

    private List<Map<String, Object>> mapDrops(JsonObject root, boolean includePlayer)
    {
        List<Map<String, Object>> drops = new ArrayList<>();
        if (root == null || !root.has("drops")) return drops;
        for (JsonElement el : root.getAsJsonArray("drops"))
        {
            JsonObject d = el.getAsJsonObject();
            Map<String, Object> drop = new LinkedHashMap<>();
            if (includePlayer) drop.put("player", str(d, "rsn"));
            drop.put("item", str(d, "itemName"));
            drop.put("itemId", d.has("itemId") && !d.get("itemId").isJsonNull() ? d.get("itemId").getAsInt() : 0);
            drop.put("value", d.has("value") ? d.get("value").getAsLong() : 0L);
            drop.put("monster", str(d, "monsterName"));
            drop.put("kc", d.has("killCount") && !d.get("killCount").isJsonNull() ? d.get("killCount").getAsInt() : 0);
            drop.put("points", d.has("points") ? d.get("points").getAsDouble() : 0.0);
            drop.put("timestamp", str(d, "createdAt"));
            drops.add(drop);
        }
        return drops;
    }

    /** GET /whitelist → items. Keys: item, source, points, dropRate, kph, category. */
    public List<Map<String, String>> fetchClanWhitelist(String base, String slug, String key) throws IOException
    {
        List<Map<String, String>> items = new ArrayList<>();
        JsonObject root = get(base, slug, key, "/whitelist", null);
        if (root == null || !root.has("whitelist")) return items;
        for (JsonElement el : root.getAsJsonArray("whitelist"))
        {
            JsonObject d = el.getAsJsonObject();
            Map<String, String> item = new LinkedHashMap<>();
            item.put("item", str(d, "itemName"));
            item.put("source", d.has("source") && !d.get("source").isJsonNull() ? d.get("source").getAsString() : "");
            item.put("points", d.has("points") && !d.get("points").isJsonNull() ? fmtPts(d.get("points").getAsDouble()) : "0");
            item.put("dropRate", "");
            item.put("kph", "");
            item.put("category", d.has("category") && !d.get("category").isJsonNull() ? d.get("category").getAsString() : "");
            items.add(item);
        }
        return items;
    }
}

