    private void refreshClanWhitelist()
    {
        if (!isPlatformConfigured())
        {
            // Show cached if available
            if (cachedClanWhitelist != null && !cachedClanWhitelist.isEmpty())
            {
                panel.updateClanWhitelist(cachedClanWhitelist);
            }
