    /** Populate the Members tab from the roster. */
    public void setMemberList(java.util.List<PlatformApiService.RosterMember> members)
    {
        SwingUtilities.invokeLater(() ->
        {
            currentMembers = members != null ? members : new java.util.ArrayList<>();
            renderMemberList();
        });
    }

    private void renderMemberList()
    {
        membersContent.removeAll();
        String q = memberSearchField.getText() == null ? "" : memberSearchField.getText().trim().toLowerCase();

        if (currentMembers.isEmpty())
        {
            JLabel none = new JLabel("No members loaded");
            none.setFont(READABLE_FONT_ITALIC);
            none.setForeground(new Color(100, 100, 100));
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            membersContent.add(none);
        }
        else
        {
            // Teams and members share ONE list, sorted by name — a team is a shared account among
            // the members, not a pinned section. Rows carry a sort name + the render callback.
            java.util.List<Object[]> rows = new java.util.ArrayList<>();
            for (PlatformApiService.TeamSummary t : currentTeams)
            {
                if (!q.isEmpty() && !t.name.toLowerCase().contains(q)
                    && t.members.stream().noneMatch(mm -> mm.rsn.toLowerCase().contains(q))) continue;
                // Teams match on their flavour/kind (gim/hcgim/unranked_gim); custom teams have no
                // game mode, so an active filter hides them.
                if (!memberModeFilter.isEmpty() && !memberModeFilter.contains(t.kind)) continue;
                rows.add(new Object[]{ t.name.toLowerCase(), (java.util.function.Supplier<JComponent>) () -> buildTeamRow(t) });
            }
            for (PlatformApiService.RosterMember m : currentMembers)
            {
                if (!q.isEmpty() && !m.rsn.toLowerCase().contains(q)) continue;
                if (!memberModeFilter.isEmpty() && !memberModeFilter.contains(normalizeAccountType(m.accountType))) continue;
                rows.add(new Object[]{ m.rsn.toLowerCase(), (java.util.function.Supplier<JComponent>) () -> buildMemberRow(m) });
            }
            rows.sort((a, b) -> ((String) a[0]).compareTo((String) b[0]));

            int shown = 0;
            for (Object[] r : rows)
            {
                if (shown >= 80)
                {
                    JLabel more = new JLabel("…refine your search to see more");
                    more.setFont(READABLE_FONT_ITALIC);
                    more.setForeground(new Color(100, 100, 100));
                    more.setAlignmentX(Component.LEFT_ALIGNMENT);
                    membersContent.add(more);
                    break;
                }
                @SuppressWarnings("unchecked")
                java.util.function.Supplier<JComponent> build = (java.util.function.Supplier<JComponent>) r[1];
                membersContent.add(build.get());
                membersContent.add(Box.createVerticalStrut(2));
                shown++;
            }
            if (shown == 0)
            {
                JLabel none = new JLabel("No members match");
                none.setFont(READABLE_FONT_ITALIC);
                none.setForeground(new Color(100, 100, 100));
                none.setAlignmentX(Component.LEFT_ALIGNMENT);
                membersContent.add(none);
            }
        }
        membersContent.revalidate();
        membersContent.repaint();
    }

    // The game's own chat-badge sprites (mod icons) keyed by account type — set from the client
    // once logged in, so the panel shows the EXACT helm icons the game puts before names.
    private final java.util.Map<String, javax.swing.ImageIcon> accountTypeIcons = new java.util.HashMap<>();

    public void setAccountTypeIcons(java.util.Map<String, java.awt.image.BufferedImage> icons)
    {
        SwingUtilities.invokeLater(() ->
        {
            for (java.util.Map.Entry<String, java.awt.image.BufferedImage> e : icons.entrySet())
            {
                accountTypeIcons.put(e.getKey(), new javax.swing.ImageIcon(e.getValue()));
            }
            renderMemberList(); // re-render so already-visible rows pick the icons up
        });
    }

    /** The in-game helm icon for an account type; null for regular/unknown or before login. */
    private javax.swing.ImageIcon accountTypeIcon(String type)
    {
        return type == null ? null : accountTypeIcons.get(type);
    }

    /** Fallback text tag for when the game icons aren't available yet (e.g. dev client). */
    private JLabel accountTypeBadge(String type)
    {
        if (type == null) return null;
        String label;
        Color color;
        switch (type)
        {
            case "ironman": label = "IM"; color = new Color(160, 160, 160); break;
            case "hardcore": label = "HC"; color = new Color(220, 90, 90); break;
            case "ultimate": label = "UIM"; color = new Color(200, 200, 185); break;
            case "gim": label = "GIM"; color = new Color(90, 190, 120); break;
            case "hcgim": label = "HCGIM"; color = new Color(220, 90, 90); break;
            case "unranked_gim": label = "UGIM"; color = new Color(140, 150, 165); break;
            default: return null; // regular needs no badge
        }
        JLabel l = new JLabel(label);
        l.setFont(READABLE_FONT_SMALL.deriveFont(Font.BOLD, 9f));
        l.setForeground(color);
        return l;
    }

    /**
     * The new-member leaf, drawn rather than typed. A 🌱 emoji renders as a blank box in the panel's
     * RuneScape font, so the icon is painted with Graphics2D: two mirrored curves for the blade and a
     * midrib, in the same green as the GIM badge. Cached — it is identical for every member.
     */
    private javax.swing.ImageIcon newMemberLeafIcon;

    private javax.swing.ImageIcon newMemberLeaf()
    {
        if (newMemberLeafIcon != null) return newMemberLeafIcon;
        int s = 10;
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(s, s, java.awt.image.BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        java.awt.geom.Path2D.Float blade = new java.awt.geom.Path2D.Float();
        blade.moveTo(1.5f, 8.5f);                       // stem end
        blade.quadTo(1.5f, 1.5f, 8.5f, 1.5f);           // outer edge, up and over
        blade.quadTo(8.5f, 8.5f, 1.5f, 8.5f);           // inner edge, back down
        blade.closePath();
        g.setColor(new Color(90, 190, 120));
        g.fill(blade);
        g.setColor(new Color(60, 140, 85));
        g.setStroke(new BasicStroke(1f));
        g.draw(new java.awt.geom.Line2D.Float(2f, 8f, 7.5f, 2.5f)); // midrib
        g.dispose();
        newMemberLeafIcon = new javax.swing.ImageIcon(img);
        return newMemberLeafIcon;
    }

    /** The leaf as a label, or null when the member is not new. */
    private JLabel newMemberBadge(boolean isNew)
    {
        if (!isNew) return null;
        JLabel l = new JLabel(newMemberLeaf());
        l.setToolTipText("New to the clan — say hi!");
        return l;
    }

    // The six ironman account types in display order (Solus is ironman-only, so no Main), each with
    // a short text fallback for when the game's helm sprites aren't loaded yet. Keys match accountType.
    private static final String[][] GAME_MODE_MODES = {
        { "ironman",      "IM"    },
        { "hardcore",     "HCIM"  },
        { "ultimate",     "UIM"   },
        { "gim",          "GIM"   },
        { "hcgim",        "HCGIM" },
        { "unranked_gim", "UGIM"  },
    };

    /** Normalize an account type for filtering; null/unknown becomes "regular". */
    private static String normalizeAccountType(String type)
    {
        if (type == null) return "regular";
        switch (type.toLowerCase())
        {
            case "ironman":      return "ironman";
            case "hardcore":     return "hardcore";
            case "ultimate":     return "ultimate";
            case "gim":          return "gim";
            case "hcgim":        return "hcgim";
            case "unranked_gim": return "unranked_gim";
            default:             return "regular";
        }
    }

    /**
     * A collapsible game-mode filter: a funnel toggle that shows/hides a row of seven helm
     * toggles (one per account type, using the in-game helm icons with a short text fallback).
     * Selecting helms narrows a list to those game modes; onChange fires with a copy of the
     * selected keys on every change. Collapsing the funnel clears the selection and fires
     * onChange with an empty set (meaning "show everything").
     */
    /** A small funnel/filter icon drawn at runtime; the panel font can't render a caret glyph reliably. */
    private static javax.swing.ImageIcon funnelIcon()
    {
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(14, 14, java.awt.image.BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D g = img.createGraphics();
        g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(210, 210, 210));
        java.awt.geom.Path2D.Float p = new java.awt.geom.Path2D.Float();
        p.moveTo(2, 3); p.lineTo(12, 3); p.lineTo(8.5f, 7.5f); p.lineTo(8.5f, 12f); p.lineTo(5.5f, 12f); p.lineTo(5.5f, 7.5f); p.closePath();
        g.fill(p);
        g.dispose();
        return new javax.swing.ImageIcon(img);
    }

    private JComponent buildGameModeFilter(java.util.function.Consumer<java.util.Set<String>> onChange)
    {
        final java.util.Set<String> selected = new java.util.LinkedHashSet<>();
        final Color offBg = new Color(40, 40, 40);
        final Color offBorder = new Color(60, 60, 60);
        final Color onBg = new Color(70, 90, 120);
        final Color onBorder = new Color(120, 170, 255);

        JPanel holder = new JPanel();
        holder.setLayout(new BoxLayout(holder, BoxLayout.Y_AXIS));
        holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
        holder.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel helmRow = new JPanel(new GridLayout(1, GAME_MODE_MODES.length, 2, 0));
        helmRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        helmRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        helmRow.setMaximumSize(new Dimension(PINNED_WIDTH, 26));
        helmRow.setVisible(false);

        for (String[] mode : GAME_MODE_MODES)
        {
            final String key = mode[0];
            final JToggleButton b = new JToggleButton();
            javax.swing.ImageIcon icon = accountTypeIcon(key);
            if (icon != null) b.setIcon(icon); else b.setText(mode[1]);
            b.setFont(READABLE_FONT_SMALL);
            b.setForeground(new Color(210, 210, 210));
            b.setBackground(offBg);
            b.setOpaque(true);
            b.setFocusPainted(false);
            b.setMargin(new Insets(2, 4, 2, 4));
            b.setToolTipText(mode[1]);
            b.setBorder(BorderFactory.createLineBorder(offBorder));
            b.addActionListener(e ->
            {
                if (b.isSelected())
                {
                    selected.add(key);
                    b.setBackground(onBg);
                    b.setBorder(BorderFactory.createLineBorder(onBorder));
                }
                else
                {
                    selected.remove(key);
                    b.setBackground(offBg);
                    b.setBorder(BorderFactory.createLineBorder(offBorder));
                }
                onChange.accept(new java.util.LinkedHashSet<>(selected));
            });
            helmRow.add(b);
        }

        final JToggleButton funnel = new JToggleButton(funnelIcon());
        funnel.setFont(READABLE_FONT_SMALL);
        funnel.setForeground(new Color(180, 180, 180));
        funnel.setBackground(offBg);
        funnel.setOpaque(true);
        funnel.setFocusPainted(false);
        funnel.setMargin(new Insets(2, 8, 2, 8));
        funnel.setToolTipText("Filter by game mode");
        funnel.addActionListener(e ->
        {
            boolean open = funnel.isSelected();
            helmRow.setVisible(open);
            if (!open)
            {
                selected.clear();
                for (Component c : helmRow.getComponents())
                {
                    if (c instanceof JToggleButton)
                    {
                        JToggleButton hb = (JToggleButton) c;
                        hb.setSelected(false);
                        hb.setBackground(offBg);
                        hb.setBorder(BorderFactory.createLineBorder(offBorder));
                    }
                }
                onChange.accept(new java.util.LinkedHashSet<>());
            }
            holder.revalidate();
            holder.repaint();
        });

        JPanel funnelRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
        funnelRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
        funnelRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        funnelRow.setMaximumSize(new Dimension(PINNED_WIDTH, 28));
        funnelRow.add(funnel);

        holder.add(funnelRow);
        holder.add(helmRow);
        return holder;
    }

    /** A shared-team row: gold name + GIM helm + account count; opens the team's shared profile. */
    private JPanel buildTeamRow(PlatformApiService.TeamSummary t)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        row.setBackground(new Color(44, 42, 33)); // faint gold tint so teams read as special
        row.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(new Color(70, 66, 45)),
            new EmptyBorder(7, 10, 7, 10)));
