        statLbl.setForeground(new Color(170, 170, 170));
        statLbl.setHorizontalAlignment(SwingConstants.RIGHT);
        statLbl.setVerticalAlignment(SwingConstants.TOP);
        row.add(statLbl, BorderLayout.EAST);

