    /** One clickable standings row; reuses buildClogProgressCard's "X / Y" card, highlighted when selected.
     *  For the most_drops win condition the team's total drops are appended to the label so the metric
     *  that decides the winner is visible alongside the slots-filled progress bar. */
    private JPanel raidRaceStandingRow(int rank, PlatformApiService.ClogRaceStanding standing, int boardSize, boolean mostDrops)
    {
        String label = rank + ". " + standing.name;
        if (mostDrops)
        {
            label += " (" + standing.drops + (standing.drops == 1 ? " drop)" : " drops)");
        }
        JPanel card = buildClogProgressCard(label, standing.count, boardSize);
        boolean selected = standing.teamId.equals(selectedRaidTeamId);
        if (selected)
        {
            card.setBackground(new Color(50, 45, 30));
            card.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ACCENT_GOLD, 1),
                new EmptyBorder(5, 7, 5, 7)));
            for (Component c : card.getComponents())
            {
                if (c instanceof JPanel) c.setBackground(card.getBackground());
            }
        }
        card.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        makeCardClickable(card, () ->
        {
            selectedRaidTeamId = standing.teamId;
            updateRaidRace(currentRaidRace);
        });
        return card;
    }

    /** For the selected team: board items grouped by their own source (host-selected boss/raid),
     *  each source a "filled / total" header + a 5-wide icon grid (alpha-dim technique from iconCell). */
    private JPanel raidRaceBoardPanel(PlatformApiService.ClogRace race, String teamId)
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);

        panel.add(clogTitle("Board", ACCENT_GOLD, 13f));
        panel.add(Box.createVerticalStrut(4));

        if (teamId == null || race.board == null || race.board.isEmpty())
        {
            JLabel none = new JLabel("No board items yet");
            none.setFont(READABLE_FONT_ITALIC);
            none.setForeground(new Color(100, 100, 100));
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            panel.add(none);
            return panel;
        }

        // "Team filled boardItem" = any fill matching both teamId and boardItemId.
        java.util.Set<String> filledIds = new java.util.HashSet<>();
        java.util.Map<String, String> filledByRsn = new java.util.HashMap<>();
        if (race.fills != null)
        {
            for (PlatformApiService.ClogRaceFill fill : race.fills)
            {
                if (teamId.equals(fill.teamId))
                {
                    filledIds.add(fill.boardItemId);
                    filledByRsn.put(fill.boardItemId, fill.filledByRsn);
                }
            }
        }

        // Group into contiguous sections by (tab, source): the board is already ordered by
        // sortOrder, so a run of items sharing the same tab+source forms one section, in the
        // exact order they first appear. The source IS the display label now (no fixed raid map).
        java.util.List<java.util.List<PlatformApiService.ClogRaceBoardItem>> sections = new java.util.ArrayList<>();
        java.util.List<String> sectionLabels = new java.util.ArrayList<>();
        String lastTab = null;
        String lastSource = null;
        for (PlatformApiService.ClogRaceBoardItem item : race.board)
        {
            boolean sameSection = !sections.isEmpty()
                && java.util.Objects.equals(item.tab, lastTab)
                && java.util.Objects.equals(item.source, lastSource);
            if (!sameSection)
            {
                sections.add(new java.util.ArrayList<>());
                sectionLabels.add(item.source != null && !item.source.isEmpty() ? item.source
                    : (item.tab != null && !item.tab.isEmpty() ? item.tab : "Unknown"));
                lastTab = item.tab;
                lastSource = item.source;
            }
            sections.get(sections.size() - 1).add(item);
        }

        for (int sectionIdx = 0; sectionIdx < sections.size(); sectionIdx++)
        {
            java.util.List<PlatformApiService.ClogRaceBoardItem> items = sections.get(sectionIdx);
            if (items.isEmpty()) continue; // omit sections with no board items

            String label = sectionLabels.get(sectionIdx);
            int filled = 0;
            for (PlatformApiService.ClogRaceBoardItem item : items)
            {
                if (filledIds.contains(item.id)) filled++;
            }
            panel.add(buildClogProgressCard(label, filled, items.size()));
            panel.add(Box.createVerticalStrut(4));

            JPanel grid = new JPanel(new GridLayout(0, 5, 3, 3));
            grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
            for (PlatformApiService.ClogRaceBoardItem item : items)
            {
                boolean filledFlag = filledIds.contains(item.id);
                grid.add(raidRaceIconCell(item, filledFlag, filledByRsn.get(item.id)));
            }

            JPanel holder = new JPanel(new BorderLayout());
            holder.setBackground(ColorScheme.DARK_GRAY_COLOR);
            holder.setAlignmentX(Component.LEFT_ALIGNMENT);
            holder.add(grid, BorderLayout.NORTH);
            panel.add(holder);
            panel.add(Box.createVerticalStrut(8));
        }

        return panel;
    }

    /** For the selected team: each member and how many board slots they were first to fill (fills
     *  contributed), sorted most-to-least. Sourced from the read shape's contributions array. */
    private JPanel raidRaceContributionsPanel(PlatformApiService.ClogRace race, String teamId)
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);

        panel.add(clogTitle("Member contributions", ACCENT_GOLD, 13f));
        panel.add(Box.createVerticalStrut(4));

        java.util.List<PlatformApiService.ClogRaceContribution> rows = new java.util.ArrayList<>();
        if (teamId != null && race.contributions != null)
        {
            for (PlatformApiService.ClogRaceContribution c : race.contributions)
            {
                if (teamId.equals(c.teamId)) rows.add(c);
            }
        }
        rows.sort((a, b) -> Integer.compare(b.fills, a.fills));

        if (rows.isEmpty())
        {
            JLabel none = new JLabel("No contributions yet");
            none.setFont(READABLE_FONT_ITALIC);
            none.setForeground(new Color(100, 100, 100));
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            panel.add(none);
            return panel;
        }

        for (PlatformApiService.ClogRaceContribution c : rows)
        {
            JPanel row = new JPanel(new BorderLayout());
            row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            row.setBorder(new EmptyBorder(4, 7, 4, 7));
            row.setAlignmentX(Component.LEFT_ALIGNMENT);

            JLabel nameLbl = new JLabel(c.rsn);
            nameLbl.setFont(READABLE_FONT);
            nameLbl.setForeground(Color.WHITE);

            JLabel fillsLbl = new JLabel(c.fills + (c.fills == 1 ? " fill" : " fills"));
            fillsLbl.setFont(READABLE_FONT_SMALL);
            fillsLbl.setForeground(new Color(180, 180, 180));

            row.add(nameLbl, BorderLayout.WEST);
            row.add(fillsLbl, BorderLayout.EAST);
            panel.add(row);
            panel.add(Box.createVerticalStrut(3));
        }

        return panel;
    }

    /** A single board-item cell: local game icon, bright when this team filled it, faded when not.
     *  Copies iconCell's alpha-dim technique (ClanPanel.java ~2822). NOTE: iconCell's own tooltip has
     *  an em dash before "missing"; that punctuation is intentionally NOT copied here, this uses
     *  " (missing)" instead. */
    private JComponent raidRaceIconCell(PlatformApiService.ClogRaceBoardItem item, boolean filled, String filledByRsn)
    {
        final float alpha = filled ? 1.0f : 0.22f;
        JLabel label = new JLabel()
        {
            @Override protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
                super.paintComponent(g2);
                g2.dispose();
            }
        };
        label.setHorizontalAlignment(SwingConstants.CENTER);
        label.setPreferredSize(new Dimension(36, 32));

        String tooltip = item.itemName;
        if (filled)
        {
            if (filledByRsn != null) tooltip += " (filled by " + filledByRsn + ")";
        }
        else
        {
            tooltip += " (missing)";
        }
        label.setToolTipText(tooltip);

        if (itemManager != null && item.itemId > 0)
        {
            AsyncBufferedImage img = itemManager.getImage(item.itemId);
            label.setIcon(new ImageIcon(img));
            img.onLoaded(() -> { label.setIcon(new ImageIcon(img)); label.revalidate(); label.repaint(); });
        }

        // Show WHO got the drop right under the icon, not just in the tooltip.
        if (filled && filledByRsn != null && !filledByRsn.isEmpty())
        {
            JPanel cell = new JPanel(new BorderLayout());
            cell.setOpaque(false);
            cell.setToolTipText(tooltip);
            cell.add(label, BorderLayout.CENTER);
            JLabel who = new JLabel(filledByRsn, SwingConstants.CENTER);
            who.setFont(who.getFont().deriveFont(9f));
            who.setForeground(new Color(160, 160, 160));
            who.setToolTipText(filledByRsn);
            cell.add(who, BorderLayout.SOUTH);
            return cell;
        }
        return label;
    }

