    private void addMouseRecursive(Component c, MouseAdapter ma)
    {
        c.addMouseListener(ma);
        if (c instanceof Container)
        {
            for (Component child : ((Container) c).getComponents()) addMouseRecursive(child, ma);
        }
    }

