                        rightPanel.add(ptLabel);
                    }

                    row.add(rightPanel, BorderLayout.EAST);
                    dropsRecentPanel.add(row);
                }
            }

            dropsRecentPanel.revalidate();
            dropsRecentPanel.repaint();
        });
    }

