@Slf4j
@Singleton
public class PlatformApiService
{
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    /**
     * Separate client for requests carrying a screenshot. A native-resolution PNG can be 16MB, which
     * travels base64 inside JSON at roughly 21MB, and callTimeout caps the WHOLE call: at 30s that
     * body fails on any connection slower than about 6 Mbps up, losing the drop entirely rather than
     * just the picture. Uploads therefore get no call timeout and a long write timeout, so a genuinely
     * stalled connection still dies while a merely slow one is allowed to finish.
     */
    private final OkHttpClient uploadClient;
    private final Gson gson;

    // The logged-in account's immutable RuneLite account hash, set by the plugin on login.
    // Stamped into player-data payloads so the backend keys identity on the account (not the
    // RSN), making history rename-proof. Null until an account is logged in.
    private volatile String accountHash;

    @Inject
    public PlatformApiService(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = httpClient.newBuilder()
            .callTimeout(30, TimeUnit.SECONDS)
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(30, TimeUnit.SECONDS)
            .writeTimeout(30, TimeUnit.SECONDS)
            // Every URL this plugin calls is the one hardcoded address. A redirect is a URL chosen
            // by the response rather than by us, so following one would take it somewhere that is
            // neither hardcoded nor entered by the user. Declined, here and on every other client.
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
        // Shares the parent's connection pool and dispatcher; only the timeouts differ.
        this.uploadClient = httpClient.newBuilder()
            .callTimeout(0, TimeUnit.SECONDS)   // 0 = no cap on the overall call
            .connectTimeout(10, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(300, TimeUnit.SECONDS)
            .followRedirects(false)
            .followSslRedirects(false)
            .build();
        this.gson = gson;
    }

    /** Set (or clear, with null) the current account hash. Called by the plugin on login/logout. */
    public void setAccountHash(String accountHash)
    {
        this.accountHash = accountHash;
    }

    public String getAccountHash()
    {
        return accountHash;
    }

    /** Stamp the current account hash onto a player-data payload when known. */
    private void addAccountHash(JsonObject payload)
    {
        if (accountHash != null && !accountHash.isEmpty())
        {
            payload.addProperty("accountHash", accountHash);
        }
    }

    /**
     * Submit a drop to the platform API.
     */
    public void submitDrop(String baseUrl, String apiKey, String clanSlug, DropEntry drop, String screenshotB64,
                           boolean discordShare, String phrase)
    {
        submitDrop(baseUrl, apiKey, clanSlug, drop, screenshotB64, discordShare, phrase, false, 0, 0);
    }

    public void submitDrop(String baseUrl, String apiKey, String clanSlug, DropEntry drop, String screenshotB64,
                           boolean discordShare, String phrase, boolean fromClog)
    {
        submitDrop(baseUrl, apiKey, clanSlug, drop, screenshotB64, discordShare, phrase, fromClog, 0, 0);
    }

    // fromClog = this "drop" is a collection-log unlock; the server posts it to the feed regardless
    // of its notable-value gate (every clog unlock is worth posting).
    //
    // clogObtained/clogTotal are the game's authoritative varp counts read at the MOMENT of the
    // unlock. They matter because the stored counts on the server are only refreshed when the player
    // opens their collection log, so without these the post would show a stale total that does not
    // include the unlock being announced. Pass 0 when not applicable.
    public void submitDrop(String baseUrl, String apiKey, String clanSlug, DropEntry drop, String screenshotB64,
                           boolean discordShare, String phrase, boolean fromClog,
                           int clogObtained, int clogTotal)
    {
        JsonObject payload = new JsonObject();
        payload.addProperty("rsn", drop.getPlayerName());
        addAccountHash(payload);
        payload.addProperty("itemName", drop.getItemName());
        if (drop.getItemId() > 0)
        {
            payload.addProperty("itemId", drop.getItemId());
        }
        payload.addProperty("value", drop.getValue());
        payload.addProperty("monsterName", drop.getMonsterName());
        if (drop.getKillCount() > 0)
        {
            payload.addProperty("killCount", drop.getKillCount());
        }
        if (screenshotB64 != null)
        {
            payload.addProperty("screenshot", screenshotB64);
        }
        // Per-player opt-in: only when discordShare is true does the server post this drop to the
        // clan's Discord. phrase is the player's own caption (Dink-style), shown above the embed.
        payload.addProperty("discordShare", discordShare);
        if (discordShare && phrase != null && !phrase.trim().isEmpty())
        {
            payload.addProperty("phrase", phrase.trim());
        }
        if (fromClog) payload.addProperty("fromClog", true);
        if (clogObtained > 0) payload.addProperty("clogObtained", clogObtained);
        if (clogTotal > 0) payload.addProperty("clogTotal", clogTotal);

        postAsync(baseUrl + "/clans/" + clanSlug + "/drops", apiKey, payload, "Platform drop");
    }

    /**
     * Report a death to the platform (Discord-only, opt-in). Called solely when the player enabled
     * "Send screenshots to Discord", so this is always a consented post. The server forwards the
     * screenshot + caption to the clan's deaths webhook; nothing is stored.
