    /**
     * Fetch the clan's current clog race (event + board + teams + fills + standings) for the
     * read-only Raid Race tab. Returns null when there is no current event (404) or on any
     * request/parse failure.
     */
    public ClogRace fetchClogRace(String baseUrl, String apiKey, String clanSlug)
    {
        JsonObject root = getSync(baseUrl + "/clans/" + clanSlug + "/clog-events/current", apiKey);
        if (root == null) return null;

        try
        {
            ClogRaceEvent event = null;
            if (root.has("event") && root.get("event").isJsonObject())
            {
                JsonObject e = root.getAsJsonObject("event");
                String hostUsername = null;
                if (e.has("host") && e.get("host").isJsonObject())
                {
                    JsonObject h = e.getAsJsonObject("host");
                    if (h.has("username") && !h.get("username").isJsonNull()) hostUsername = h.get("username").getAsString();
                }
                event = new ClogRaceEvent(
                    e.has("id") && !e.get("id").isJsonNull() ? e.get("id").getAsString() : null,
                    e.has("name") && !e.get("name").isJsonNull() ? e.get("name").getAsString() : "",
                    e.has("status") && !e.get("status").isJsonNull() ? e.get("status").getAsString() : null,
                    e.has("startTime") && !e.get("startTime").isJsonNull() ? e.get("startTime").getAsString() : null,
                    e.has("endTime") && !e.get("endTime").isJsonNull() ? e.get("endTime").getAsString() : null,
                    e.has("winnerTeamId") && !e.get("winnerTeamId").isJsonNull() ? e.get("winnerTeamId").getAsString() : null,
                    e.has("winCondition") && !e.get("winCondition").isJsonNull() ? e.get("winCondition").getAsString() : null,
                    hostUsername);
            }

            List<ClogRaceBoardItem> board = new ArrayList<>();
            if (root.has("board") && root.get("board").isJsonArray())
            {
                for (JsonElement el : root.getAsJsonArray("board"))
                {
                    JsonObject o = el.getAsJsonObject();
                    board.add(new ClogRaceBoardItem(
                        o.has("id") && !o.get("id").isJsonNull() ? o.get("id").getAsString() : null,
                        o.has("itemName") && !o.get("itemName").isJsonNull() ? o.get("itemName").getAsString() : "",
                        o.has("itemId") && !o.get("itemId").isJsonNull() ? o.get("itemId").getAsInt() : 0,
                        o.has("source") && !o.get("source").isJsonNull() ? o.get("source").getAsString() : null,
                        o.has("tab") && !o.get("tab").isJsonNull() ? o.get("tab").getAsString() : null,
                        o.has("isHardMode") && !o.get("isHardMode").isJsonNull() && o.get("isHardMode").getAsBoolean(),
                        o.has("sortOrder") && !o.get("sortOrder").isJsonNull() ? o.get("sortOrder").getAsInt() : 0));
                }
            }

            List<ClogRaceTeam> teams = new ArrayList<>();
            if (root.has("teams") && root.get("teams").isJsonArray())
            {
                for (JsonElement el : root.getAsJsonArray("teams"))
                {
                    JsonObject o = el.getAsJsonObject();
                    List<String> members = new ArrayList<>();
                    if (o.has("members") && o.get("members").isJsonArray())
                        for (JsonElement m : o.getAsJsonArray("members")) members.add(m.getAsString());
                    teams.add(new ClogRaceTeam(
                        o.has("teamId") && !o.get("teamId").isJsonNull() ? o.get("teamId").getAsString() : null,
                        o.has("name") && !o.get("name").isJsonNull() ? o.get("name").getAsString() : "",
                        o.has("color") && !o.get("color").isJsonNull() ? o.get("color").getAsString() : null,
                        members));
                }
            }

            List<ClogRaceFill> fills = new ArrayList<>();
            if (root.has("fills") && root.get("fills").isJsonArray())
            {
                for (JsonElement el : root.getAsJsonArray("fills"))
                {
                    JsonObject o = el.getAsJsonObject();
                    fills.add(new ClogRaceFill(
                        o.has("teamId") && !o.get("teamId").isJsonNull() ? o.get("teamId").getAsString() : null,
                        o.has("boardItemId") && !o.get("boardItemId").isJsonNull() ? o.get("boardItemId").getAsString() : null,
                        o.has("filledByRsn") && !o.get("filledByRsn").isJsonNull() ? o.get("filledByRsn").getAsString() : null,
                        o.has("method") && !o.get("method").isJsonNull() ? o.get("method").getAsString() : null,
                        o.has("filledAt") && !o.get("filledAt").isJsonNull() ? o.get("filledAt").getAsString() : null));
                }
            }

            List<ClogRaceStanding> standings = new ArrayList<>();
            if (root.has("standings") && root.get("standings").isJsonArray())
            {
                for (JsonElement el : root.getAsJsonArray("standings"))
                {
                    JsonObject o = el.getAsJsonObject();
                    standings.add(new ClogRaceStanding(
                        o.has("teamId") && !o.get("teamId").isJsonNull() ? o.get("teamId").getAsString() : null,
                        o.has("name") && !o.get("name").isJsonNull() ? o.get("name").getAsString() : "",
                        o.has("count") && !o.get("count").isJsonNull() ? o.get("count").getAsInt() : 0,
                        o.has("drops") && !o.get("drops").isJsonNull() ? o.get("drops").getAsInt() : 0,
                        o.has("reachedAt") && !o.get("reachedAt").isJsonNull() ? o.get("reachedAt").getAsString() : null));
                }
            }

            List<ClogRaceContribution> contributions = new ArrayList<>();
            if (root.has("contributions") && root.get("contributions").isJsonArray())
            {
                for (JsonElement el : root.getAsJsonArray("contributions"))
                {
                    JsonObject o = el.getAsJsonObject();
                    contributions.add(new ClogRaceContribution(
                        o.has("teamId") && !o.get("teamId").isJsonNull() ? o.get("teamId").getAsString() : null,
                        o.has("rsn") && !o.get("rsn").isJsonNull() ? o.get("rsn").getAsString() : "",
                        o.has("fills") && !o.get("fills").isJsonNull() ? o.get("fills").getAsInt() : 0));
                }
            }

            return new ClogRace(event, board, teams, fills, standings, contributions);
        }
        catch (Exception ex)
        {
            log.debug("parse clog-race failed: {}", ex.getMessage());
            return null;
        }
    }

    // ══════════════════════════════════════════
    // Bingo (team boards, /clans/:slug/bingo/current and /players/:rsn)
    // ══════════════════════════════════════════

    /** Bingo event header. No win-rule field: the API's public settings whitelist is exactly
     *  { rows, cols, teamSize, hasDraft } (GET .../current, .../:id) - winRule is never returned
     *  to the client. The rule is fixed anyway (most points at end time; completing every tile ends
     *  the event early), so there is nothing to read or show here. */
    public static class BingoEvent
    {
        public final String id;
        public final String name;
        public final String status;
        public final String startTime;
        public final String endTime;
        public final String winnerTeamId;
        /** Whether to show the board yet: false until the draft is complete or the bingo has started
         *  (server event.boardReady). True when an older server does not send it, so nothing changes there. */
        public final boolean boardReady;
        public BingoEvent(String id, String name, String status, String startTime, String endTime,
                           String winnerTeamId)
        {
            this(id, name, status, startTime, endTime, winnerTeamId, true);
        }
        public BingoEvent(String id, String name, String status, String startTime, String endTime,
                           String winnerTeamId, boolean boardReady)
        {
            this.id = id; this.name = name; this.status = status;
            this.startTime = startTime; this.endTime = endTime;
            this.winnerTeamId = winnerTeamId;
            this.boardReady = boardReady;
        }
    }

    /** One item that counts toward a tile (contract's items[]; onlyFrom/note are server-enforced and
     *  not needed for display, so they are deliberately not carried into the client model). */
    public static class BingoItem
    {
        public final String itemName;
        public final int itemId;
        public final double points;
        public BingoItem(String itemName, int itemId, double points)
        { this.itemName = itemName; this.itemId = itemId; this.points = points; }
    }

    /**
     * One board tile definition (static: no progress).
     *
     * kind is the server's enum, exactly one of "drop", "kc" or "xp" (absent/unknown is treated as
     * "drop"):
     *  - "drop" scores from logged item drops and carries items[].
     *  - "kc"/"xp" score from Wise Old Man gains instead. They carry womMetric (the WOM metric slug,
     *    e.g. "vorkath" or "woodcutting") and pointsPer, have NO items at all, and never match a
     *    drop. Their points still arrive the ordinary way, in progress[teamId][code].points, so the
     *    board's gold fill works on them unchanged; only the icon has to come from somewhere else
     *    (see BingoTeamView#resolveTile, which resolves womMetric to a boss/skill sprite).
     */
    public static class BingoBoardTile
    {
        public final String code;
        public final String name;
        public final String kind;
        public final int row;
        public final int col;
        public final double threshold;
        public final double max;
        public final String icon; // boss name, item name, item id (as text), or empty -> first item
        public final List<BingoItem> items;
        public final String description; // may be null
        public final String womMetric;   // kc/xp tiles only; null on a drop tile
        public final double pointsPer;   // kc/xp tiles only; 0 when absent
        public BingoBoardTile(String code, String name, String kind, int row, int col, double threshold,
                              double max, String icon, List<BingoItem> items,
                              String description, String womMetric, double pointsPer)
        {
            this.code = code; this.name = name; this.kind = kind; this.row = row; this.col = col;
            this.threshold = threshold; this.max = max; this.icon = icon; this.items = items;
            this.description = description; this.womMetric = womMetric; this.pointsPer = pointsPer;
        }
        /** Drop-tile convenience: no description, no WOM metric. */
        public BingoBoardTile(String code, String name, String kind, int row, int col, double threshold,
