package com.droplogger;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
@Singleton
public class RsHiscoreTracker
{
    private final Client client;
    private final PlatformApiService platformApiService;
    private final ScheduledExecutorService executor;

    private final Set<String> previousOnlineMembers = new HashSet<>();
    private boolean initialized = false;
    private boolean rosterSyncedThisSession = false;

    @Inject
    public RsHiscoreTracker(Client client, PlatformApiService platformApiService,
                            ScheduledExecutorService executor)
    {
        this.client = client;
        this.platformApiService = platformApiService;
        this.executor = executor;
    }

    /**
     * Called every game tick. Tracks online clan members and detects logoffs.
     */
    public void onGameTick(String baseUrl, String apiKey, String slug, boolean enableStatTracking)
    {
        if (!enableStatTracking)
        {
            return;
        }

        if (baseUrl.isEmpty() || apiKey.isEmpty() || slug.isEmpty())
        {
            return;
        }

        ClanChannel clanChannel = client.getClanChannel();
        if (clanChannel == null)
        {
            return;
        }

        // Build current online set
        Set<String> currentOnline = new HashSet<>();
        for (ClanChannelMember member : clanChannel.getMembers())
        {
            String name = Text.toJagexName(member.getName());
            currentOnline.add(name);
        }

        if (!initialized)
        {
            // First tick — just record who is online, don't trigger snapshots
            previousOnlineMembers.addAll(currentOnline);
            initialized = true;
            return;
        }

        // Detect logoffs: was in previous set but not in current
        for (String name : previousOnlineMembers)
        {
            if (!currentOnline.contains(name))
            {
                log.debug("Clan member logged off: {}, triggering snapshot", name);
                executor.submit(() -> platformApiService.triggerSnapshot(baseUrl, apiKey, slug, name));
            }
        }

        previousOnlineMembers.clear();
        previousOnlineMembers.addAll(currentOnline);
    }

    /**
     * Sync the full clan roster from ClanSettings. Admin only.
     * Returns the number of members synced, or -1 if ClanSettings unavailable.
     */
    public int syncRoster(String baseUrl, String apiKey, String slug)
    {
        log.info("syncRoster called — url={}, key={}, slug={}",
            baseUrl.isEmpty() ? "(empty)" : baseUrl,
            apiKey.isEmpty() ? "(empty)" : "(set)",
            slug.isEmpty() ? "(empty)" : slug);

        if (baseUrl.isEmpty() || apiKey.isEmpty() || slug.isEmpty())
        {
            log.warn("syncRoster aborted — missing config");
            return -1;
        }

        ClanSettings clanSettings = client.getClanSettings();
        if (clanSettings == null)
        {
            log.warn("ClanSettings not available — is the player in a clan?");
            return -1;
        }

        List<ClanMember> members = clanSettings.getMembers();
        if (members == null || members.isEmpty())
        {
            return 0;
        }

        List<String[]> memberList = new ArrayList<>();
        for (ClanMember member : members)
        {
            String name = Text.toJagexName(member.getName());
            String rank = null;
            if (member.getRank() != null)
            {
                ClanTitle title = clanSettings.titleForRank(member.getRank());
                rank = title != null ? title.getName() : null;
            }
            String joinDate = null;
            if (member.getJoinDate() != null)
            {
                joinDate = member.getJoinDate().toString(); // ISO format: YYYY-MM-DD
            }
            memberList.add(new String[]{name, rank, joinDate});
        }

        // Send the clan NAME so the server can reject a roster synced from a different clan.
        final String clanName = clanSettings.getName();
        log.info("Syncing roster: {} members from clan '{}'", memberList.size(), clanName);
        executor.submit(() -> platformApiService.syncRoster(baseUrl, apiKey, slug, memberList, clanName));
        return memberList.size();
    }

    /**
     * Auto-sync roster on login if admin key is configured. Called once per session.
     */
    public void onLoginIfAdmin(String baseUrl, String apiKey, String slug, String adminKey)
    {
        if (rosterSyncedThisSession || adminKey == null || adminKey.isEmpty())
        {
            return;
        }

        rosterSyncedThisSession = true;
        int count = syncRoster(baseUrl, apiKey, slug);
        if (count > 0)
        {
            log.info("Auto-synced roster on login: {} members", count);
        }
    }

    public void reset()
    {
        previousOnlineMembers.clear();
        initialized = false;
        rosterSyncedThisSession = false;
    }
}

package com.droplogger;

import java.awt.Color;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Team colours as the server sends them. New teams are #RRGGBB; teams created before 2026-09-19 were
 * stored as names ("red"), which Color.decode cannot read, so their clan-chat dots silently never
 * drew. The names map to the same hex as the server's palette (src/lib/team-colors.ts).
 */
final class TeamColors
{
    private static final Map<String, Integer> NAMED = new HashMap<>();
    static
    {
        NAMED.put("red", 0xE53935);
        NAMED.put("blue", 0x1E88E5);
        NAMED.put("green", 0x43A047);
        NAMED.put("purple", 0x8E24AA);
        NAMED.put("orange", 0xFB8C00);
        NAMED.put("teal", 0x00897B);
        NAMED.put("pink", 0xD81B60);
        NAMED.put("yellow", 0xFDD835);
    }

    private TeamColors() {}

    /** The colour, or null when it cannot be read. Never throws. */
    static Color parse(String value)
    {
        if (value == null || value.trim().isEmpty()) return null;
        String v = value.trim();
        if (v.startsWith("#"))
        {
            try { return Color.decode(v); }
            catch (NumberFormatException e) { return null; }
        }
        Integer rgb = NAMED.get(v.toLowerCase(Locale.ROOT));
        return rgb == null ? null : new Color(rgb);
    }
}

package com.droplogger;

import org.junit.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * The server sends a tile's row/col ONE-based (a board is authored in a spreadsheet whose top-left
 * tile is row 1, col 1, and the server's tileWithinGrid rejects anything below 1). The panel used
 * to treat them as zero-based, which left the top-left cell empty and silently dropped the entire
 * last row and column off a board. The dev preview hid it by using zero-based sample data.
 */
public class BingoBoardGridTest
{
    private static BingoTile at(String code, int row, int col)
    {
        return BingoTile.item(code, code, row, col, 0, 1, 0, BingoTile.KIND_DROP, false);
    }

    @Test
    public void everyCornerOfAOneBasedBoardIsPlaced()
    {
        List<BingoTile> tiles = Arrays.asList(
            at("A1", 1, 1), at("E1", 1, 5), at("A5", 5, 1), at("E5", 5, 5), at("C3", 3, 3));

        BingoTile[][] grid = BingoBoardPanel.layOutForTest(tiles, 5, 5);

        assertNotNull("top-left tile must be placed", grid[0][0]);
        assertEquals("A1", grid[0][0].code);
        assertNotNull("last column must not be dropped", grid[0][4]);
        assertEquals("E1", grid[0][4].code);
        assertNotNull("last row must not be dropped", grid[4][0]);
        assertEquals("A5", grid[4][0].code);
        assertNotNull("bottom-right tile must be placed", grid[4][4]);
        assertEquals("E5", grid[4][4].code);
        assertEquals("C3", grid[2][2].code);
    }

    @Test
    public void aTileOutsideTheGridIsIgnoredRatherThanThrowing()
    {
        // A host who shrinks a board leaves tiles behind; the panel must not blow up on them.
        BingoTile[][] grid = BingoBoardPanel.layOutForTest(
            Arrays.asList(at("E5", 5, 5), at("Z9", 9, 9), at("bad", 0, 0)), 3, 3);
        for (BingoTile[] gridRow : grid)
        {
            for (BingoTile t : gridRow)
            {
                assertEquals(null, t);
            }
        }
    }
}

