package com.droplogger;

import com.google.gson.JsonObject;
import com.google.gson.Gson;
import org.junit.Test;
import static org.junit.Assert.*;

public class MassCardParseTest
{
    @Test
    public void parsesALiveCard()
    {
        JsonObject o = new Gson().fromJson("{\"id\":\"m1\",\"title\":\"Corp Mass\",\"bossKey\":\"corporeal_beast\",\"bossName\":\"Corporeal Beast\","
            + "\"phase\":\"live\",\"start\":\"2026-10-03T20:00:00Z\",\"end\":\"2026-10-04T01:00:00Z\",\"goingCount\":3,\"youreGoing\":true,"
            + "\"totalKills\":12,\"killsUpdatedAt\":\"2026-10-03T20:30:00Z\","
            + "\"items\":[{\"itemId\":1,\"itemName\":\"Spectral sigil\",\"count\":1}],"
            + "\"drops\":[{\"itemId\":1,\"itemName\":\"Spectral sigil\",\"rsn\":\"BlG Moby\",\"at\":\"2026-10-03T20:42:00Z\"}]}", JsonObject.class);
        PlatformApiService.MassCard c = PlatformApiService.parseMassCard(o);
        assertEquals("live", c.phase);
        assertEquals(Integer.valueOf(12), c.totalKills);
        assertTrue(c.youreGoing);
        assertEquals(1, c.items.size());
        assertEquals("BlG Moby", c.drops.get(0).rsn);
    }

    @Test
    public void parsesUnknownKillsAndNoBoss()
    {
        JsonObject o = new Gson().fromJson("{\"id\":\"m2\",\"title\":\"Mystery mass\",\"bossKey\":null,\"bossName\":null,\"phase\":\"upcoming\","
            + "\"start\":\"2026-10-03T20:00:00Z\",\"end\":\"2026-10-03T23:00:00Z\",\"goingCount\":0,\"youreGoing\":false,"
            + "\"totalKills\":null,\"killsUpdatedAt\":null,\"items\":[],\"drops\":[]}", JsonObject.class);
        PlatformApiService.MassCard c = PlatformApiService.parseMassCard(o);
        assertNull(c.totalKills);
        assertNull(c.bossName);
        assertTrue(c.items.isEmpty());
    }

    @Test
    public void parsesTheTopKillers()
    {
        JsonObject o = new Gson().fromJson("{\"id\":\"m3\",\"title\":\"Corp Mass\",\"bossName\":\"Corporeal Beast\",\"phase\":\"ended\","
            + "\"start\":\"2026-10-03T20:00:00Z\",\"end\":\"2026-10-03T22:15:00Z\",\"goingCount\":0,\"youreGoing\":false,"
            + "\"totalKills\":9,\"killsUpdatedAt\":null,\"killers\":[{\"rsn\":\"A\",\"kills\":6},{\"rsn\":\"B\",\"kills\":3}],"
            + "\"items\":[],\"drops\":[]}", JsonObject.class);
        PlatformApiService.MassCard c = PlatformApiService.parseMassCard(o);
        assertEquals(2, c.killers.size());
        assertEquals("A", c.killers.get(0).rsn);
        assertEquals(6, c.killers.get(0).kills);
    }

    @Test
    public void olderServerWithoutKillersParsesAsEmpty()
    {
        JsonObject o = new Gson().fromJson("{\"id\":\"m4\",\"title\":\"X mass\",\"phase\":\"live\",\"items\":[],\"drops\":[]}", JsonObject.class);
        assertTrue(PlatformApiService.parseMassCard(o).killers.isEmpty());
    }

    @Test
    public void durationReadsHoursAndMinutes()
    {
        assertEquals("2h 15m", MassCardPanel.duration("2026-10-03T20:00:00Z", "2026-10-03T22:15:00Z"));
        assertEquals("45m", MassCardPanel.duration("2026-10-03T20:00:00Z", "2026-10-03T20:45:00Z"));
        assertEquals("", MassCardPanel.duration(null, "2026-10-03T20:45:00Z"));
    }
}

package com.droplogger;

/**
 * Parsing sweep: real chat-message sequences through PbDetector, asserting which board
 * each time lands on. Run via `gradlew sweep`. Exits non-zero on any failure so it can
 * gate future detector changes.
 */
public class PbSweep
{
    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args)
    {
        // ── Gauntlet ──
        // count-first ordering (context set before the time line)
        seq("CG count-first", "gaunt_corrupted", "6:33.60",
            "Your Corrupted Gauntlet completion count is: 45.",
            "Challenge duration: 6:33.60. Personal best: 5:57.00.");
        // time-first ordering (cold client: park + claim)
        seq("CG time-first (parked)", "gaunt_corrupted", "6:33.60",
            "Challenge duration: 6:33.60. Personal best: 5:57.00.",
            "Your Corrupted Gauntlet completion count is: 45.");
        seq("Gauntlet normal", "gaunt", "7:39.00",
            "Your Gauntlet completion count is: 12.",
            "Challenge duration: 7:39.00 (new personal best)");
        // REGRESSION: a Gauntlet finishing while a WEAK "Chambers of Xeric" mention is still fresh
        // (e.g. a line the plugin itself printed) must NOT inherit CoX context. It has to park and
        // let the definitive Gauntlet completion-count claim it. This is the exact bug that put
        // 6-7 min "cox_solo" times on the Chambers board.
        seq("CG after weak CoX mention", "gaunt_corrupted", "5:57.00",
            "Chambers of Xeric personal best: 21:40 (rank 3).",
            "Challenge duration: 5:57.00 (new personal best)",
            "Your Corrupted Gauntlet completion count is: 46.");
        // Positive control: a real CoX "Challenge duration" still lands on CoX when the context is
        // a CONFIRMED self-completion (the count message), proving the gate didn't break Chambers.
        seq("CoX challenge, confirmed count-first", "cox", "22:15.00",
            "Your completed Chambers of Xeric count is: 471.",
            "Challenge duration: 22:15.00 (new personal best)");

        // ── Chambers of Xeric ──
        seq("CoX duration-first (parked)", "cox", "41:40.80",
            "Team size: Solo Duration: 41:40.80 Personal best: 39:53.40",
            "Your completed Chambers of Xeric count is: 470.");
        seq("CoX CM count-first", "cox_cm", "28:11.40",
            "Your completed Chambers of Xeric: Challenge Mode count is: 30.",
            "Team size: Solo Duration: 28:11.40 Personal best: 27:02.00");
        reject("CoX floor line", "Upper level complete! Duration: 4:31.00");
        reject("Olm phase line", "Olm duration: 5:20.00");

        // ── Theatre of Blood ──
        one("ToB room time", "tob", "15:07.20",
            "Theatre of Blood completion time: 15:07.20. Personal best: 13:56.40");
        reject("ToB total time", "Theatre of Blood total completion time: 17:37.80. Personal best: 16:10.20");
        one("ToB entry", "tob_entry", "18:00.00",
            "Theatre of Blood: Entry Mode completion time: 18:00.00. Personal best: 17:00.00");
        one("ToB hard", "tob_hm", "20:30.00",
            "Theatre of Blood: Hard Mode completion time: 20:30.00. Personal best: 19:00.00");
        reject("ToB room wave line", "Wave 'The Maiden of Sugadinti' complete! Duration: 2:45.00");
        reject("ToB final wave line", "Wave 'The Final Challenge' (Normal Mode) complete! Duration: 4:04.60");

        // ── Tombs of Amascut ──
        // ToA boards the TOTAL time (wall clock). Challenge time counts only time inside rooms and
        // ignores everything between them, which makes it far too easy to game.
        one("ToA expert total time", "toa_expert", "28:33.60",
            "Tombs of Amascut: Expert Mode total completion time: 28:33.60. Personal best: 26:09.00");
        reject("ToA expert challenge time", "Tombs of Amascut: Expert Mode challenge completion time: 25:33.00. Personal best: 23:12.60");
        one("ToA normal total time", "toa", "29:14.40",
            "Tombs of Amascut total completion time: 29:14.40. Personal best: 28:02.00");
        reject("ToA normal challenge time", "Tombs of Amascut challenge completion time: 26:22.00. Personal best: 25:08.00");
        // REGRESSION: ToA prints one of these per ROOM. None of the raid patterns match it, so it
        // used to reach the bare "Duration:" rule and be filed as a ToA time - the board showed the
        // Wardens fight instead of the raid.
        reject("ToA Wardens room line", "Challenge complete: The Wardens. Duration: 2:30.00");
        reject("ToA puzzle room line", "Challenge complete: Het. Duration: 1:04.20");
        // The same line must not survive by being PARKED and then claimed by the count message that
        // ends the raid: that path bypassed every ToA pattern entirely.
        rejectSeq("ToA Wardens line cannot be claimed by the raid count",
            "Challenge complete: The Wardens. Duration: 2:30.00",
            "Your completed Tombs of Amascut count is: 124.");
        // Positive control: the real sequence still boards the whole raid.
        seq("ToA full raid sequence boards the total", "toa", "29:14.40",
            "Challenge complete: The Wardens. Duration: 2:30.00",
            "Tombs of Amascut total completion time: 29:14.40. Personal best: 28:02.00");

        // ── Wave content (duration before KC) ──
        seq("Inferno parked", "zuk", "68:33.00",
            "Duration: 68:33.00. Personal best: 65:00.00",
            "Your TzKal-Zuk kill count is: 5.");
        seq("Fight Caves parked", "jad", "32:15.60",
            "Duration: 32:15.60 (new personal best)",
            "Your TzTok-Jad kill count is: 8.");
        seq("Colosseum parked", "colo", "26:56.40",
            "Colosseum duration: 26:56.40. Personal best: 25:00.00",
            "Your Sol Heredit kill count is: 3.");
        reject("Colosseum wave line", "Wave: 11 Wave duration: 2:15.00");

        // ── Bosses ──
        seq("GG kc-first", "grotesque", "1:05.40",
            "Your Grotesque Guardians kill count is: 100.",
            "Fight duration: 1:05.40. Personal best: 1:02.00");
        seq("GG fight-first (parked)", "grotesque", "1:05.40",
            "Fight duration: 1:05.40. Personal best: 1:02.00",
            "Your Grotesque Guardians kill count is: 100.");
        seq("Phosani solo", "phosanis", "5:03.00",
            "Your Phosani's Nightmare kill count is: 714.",
            "Team size: Solo Fight duration: 5:03.00. Personal best: 4:25.20");
        reject("Nightmare plugin phase line",
            "Phosani's Nightmare P4 boss complete! Duration: 0:08.40 Total: 5:03.00");
        seq("Yama", "yama", "3:21.00",
            "Your Yama kill count is: 1090.",
            "Fight duration: 3:21.00 (new personal best)");

        System.out.println("──────────────────");
        System.out.println(passed + " passed, " + failed + " failed");
        if (failed > 0) System.exit(1);
    }

    /** Feed messages in order to a FRESH detector; assert the final detected completion. */
    private static void seq(String name, String expectGroup, String expectTime, String... messages)
    {
        PbDetector d = new PbDetector();
        PbDetector.CompletionResult result = null;
        for (String m : messages)
        {
            d.processMessage(m);
            PbDetector.CompletionResult r = d.detectCompletion(m);
            if (r != null) result = r;
            PbDetector.CompletionResult drained = d.drainPendingCompletion();
            if (drained != null) result = drained;
        }
        check(name, result, expectGroup, expectTime);
    }

    /** Single message with no context must resolve on its own. */
    private static void one(String name, String expectGroup, String expectTime, String message)
    {
        seq(name, expectGroup, expectTime, message);
    }

    /**
     * A whole SEQUENCE must produce no completion. Distinct from {@link #reject}: a line can be
     * rejected on its own and still be parked, then claimed by a later count/KC message. That is
     * exactly how a ToA room time reached the board without matching any ToA pattern.
     */
    private static void rejectSeq(String name, String... messages)
    {
        PbDetector d = new PbDetector();
        PbDetector.CompletionResult found = null;
        for (String m : messages)
        {
            d.processMessage(m);
            PbDetector.CompletionResult r = d.detectCompletion(m);
            if (r != null) found = r;
            PbDetector.CompletionResult drained = d.drainPendingCompletion();
            if (drained != null) found = drained;
        }
        if (found == null)
        {
            passed++;
            System.out.println("PASS  " + name);
        }
        else
        {
            failed++;
            System.out.println("FAIL  " + name + " — unexpectedly detected " + found.getGroup() + " " + found.getFormattedTime());
        }
    }

    /** Message must NOT produce a completion (phase/progress/total lines). */
    private static void reject(String name, String message)
    {
        PbDetector d = new PbDetector();
        d.processMessage(message);
        PbDetector.CompletionResult r = d.detectCompletion(message);
        PbDetector.CompletionResult drained = d.drainPendingCompletion();
        if (r == null && drained == null)
        {
            passed++;
            System.out.println("PASS  " + name);
        }
        else
        {
            failed++;
            PbDetector.CompletionResult bad = r != null ? r : drained;
            System.out.println("FAIL  " + name + " — unexpectedly detected " + bad.getGroup() + " " + bad.getFormattedTime());
        }
    }

    private static void check(String name, PbDetector.CompletionResult r, String expectGroup, String expectTime)
    {
        if (r != null && expectGroup.equals(r.getGroup()) && expectTime.equals(r.getFormattedTime()))
        {
            passed++;
            System.out.println("PASS  " + name);
        }
        else
        {
            failed++;
            System.out.println("FAIL  " + name + " — expected " + expectGroup + " " + expectTime
                + ", got " + (r == null ? "null" : r.getGroup() + " " + r.getFormattedTime()));
        }
    }
}

package com.droplogger;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Pure parsing tests for the bingo client model: PlatformApiService.parseBingoCard/parseBingoPlayer
 * take a JsonObject and never touch the network, so a hand-built payload string exercises them
 * exactly like a real /bingo/current response would, including partial/missing-field shapes.
 */
public class PlatformApiServiceBingoTest
{
    private static final Gson GSON = new Gson();

    private JsonObject json(String s) { return GSON.fromJson(s, JsonObject.class); }

    @Test public void nullEventMeansNoCard()
    {
        PlatformApiService.BingoCard card = PlatformApiService.parseBingoCard(json("{\"event\":null}"));
        assertNotNull(card);
        assertNull(card.event);
        assertNotNull(card.teams);
        assertTrue(card.teams.isEmpty());
        assertNotNull(card.standings);
        assertNotNull(card.progress);
        assertNotNull(card.bounties);
    }

    @Test public void missingEventKeyEntirelyAlsoMeansNoCard()
    {
        PlatformApiService.BingoCard card = PlatformApiService.parseBingoCard(json("{}"));
        assertNotNull(card);
        assertNull(card.event);
    }

    @Test public void nullRootReturnsNull()
    {
        assertNull(PlatformApiService.parseBingoCard(null));
    }

    @Test public void fullShapeParsesEveryField()
    {
        // Real route shape (src/routes/bingo.ts loadFullBingoEvent): event.settings is whitelisted
        // down to { rows, cols, teamSize, hasDraft } for a public/full-detail read - no winRule, so
        // this payload includes one anyway (as a real server response never would, but a stale/future
        // field must still be silently ignored) to prove parsing never reads or stores it; board
        // tiles carry kind ("drop" | "kc" | "xp"), description, womMetric and pointsPer; teams[]
        // carries the rich per-team fields (members + points/tilesComplete/rank/gapToAbove/
        // leadOverBelow/roster/recentDrops) together; standings[] is the plain leaderboard
        // (teamId/name/color/points/tilesComplete/rank only - no gap/roster/recentDrops); a
        // progress[team][tile].drops entry has no tileCode key of its own (it's implied by the outer
        // tile-code key); a bounty sends an explicit "released" boolean, and while unreleased its
        // title reads "Bounty <number>" with a null description and empty items.
        String payload = "{"
            + "\"event\":{\"id\":\"ev1\",\"name\":\"Autumn Bingo\",\"status\":\"active\","
            + "  \"startTime\":\"2026-09-01T00:00:00Z\",\"endTime\":\"2026-09-15T00:00:00Z\","
            + "  \"winnerTeamId\":null,\"settings\":{\"rows\":2,\"cols\":2,\"winRule\":\"points\"}},"
            + "\"board\":{\"rows\":2,\"cols\":2,\"tiles\":["
            + "  {\"code\":\"A1\",\"name\":\"Zulrah\",\"row\":0,\"col\":0,\"kind\":\"drop\","
            + "   \"description\":null,\"womMetric\":null,\"pointsPer\":null,"
            + "   \"threshold\":30,\"max\":0,\"icon\":\"Zulrah\",\"items\":["
            + "     {\"itemName\":\"Zulrah's scales\",\"itemId\":12934,\"points\":1}]},"
            + "  {\"code\":\"A2\",\"name\":\"Vorkath KC\",\"row\":0,\"col\":1,\"kind\":\"kc\","
            + "   \"description\":\"One point per kill\",\"womMetric\":\"vorkath\",\"pointsPer\":1,"
            + "   \"threshold\":30,\"max\":40,\"icon\":null,\"items\":[]}"
            + "]},"
            + "\"teams\":[{\"teamId\":\"t1\",\"name\":\"Alpha\",\"color\":\"#FF0000\",\"members\":[\"Alice\",\"Bob\"],"
            + "  \"points\":30,\"tilesComplete\":1,\"rank\":1,\"gapToAbove\":null,"
            + "  \"leadOverBelow\":{\"points\":10,\"tiles\":0},"
            + "  \"roster\":[{\"rsn\":\"Alice\",\"points\":30,\"dropCount\":1}],"
            + "  \"recentDrops\":[{\"rsn\":\"Alice\",\"item\":\"Zulrah's scales\",\"tileCode\":\"A1\",\"points\":1,"
            + "     \"proofUrl\":\"https://discord.com/channels/1/2/3\",\"droppedAt\":\"2026-09-02T00:00:00Z\"}]}],"
            + "\"standings\":[{\"teamId\":\"t1\",\"name\":\"Alpha\",\"color\":\"#FF0000\",\"points\":30,"
            + "  \"tilesComplete\":1,\"rank\":1}],"
            + "\"progress\":{\"t1\":{\"A1\":{\"points\":30,\"complete\":true,\"drops\":[{\"rsn\":\"Alice\","
            + "  \"item\":\"Zulrah's scales\",\"points\":1,\"proofUrl\":null,\"droppedAt\":null}]}}},"
            + "\"bounties\":[{\"id\":\"b1\",\"number\":1,\"title\":\"Bounty 1\",\"description\":null,"
            + "  \"released\":false,\"items\":[],"
            + "  \"points\":50,\"releaseAt\":\"2026-09-10T00:00:00Z\",\"claimedTeamId\":null,\"claimedAt\":null}]"
            + "}";

        PlatformApiService.BingoCard card = PlatformApiService.parseBingoCard(json(payload));
        assertNotNull(card);
        assertEquals("ev1", card.event.id);
        assertEquals("active", card.event.status);
        assertEquals(2, card.board.rows);
        assertEquals(2, card.board.tiles.size());
        assertEquals("Zulrah", card.board.tiles.get(0).icon);
        assertEquals(1, card.board.tiles.get(0).items.size());
        assertEquals("drop", card.board.tiles.get(0).kind);
        assertFalse(card.board.tiles.get(0).isWomTile());
        assertNull(card.board.tiles.get(0).womMetric);

        // The kc tile: no items, no icon, but a metric and a points-per rate to render from.
        PlatformApiService.BingoBoardTile kc = card.board.tiles.get(1);
        assertEquals("kc", kc.kind);
        assertTrue(kc.isWomTile());
        assertEquals("vorkath", kc.womMetric);
        assertEquals(1, kc.pointsPer, 0.0001);
        assertEquals("One point per kill", kc.description);
        assertEquals(40, kc.max, 0.0001);
        assertTrue(kc.items.isEmpty());
        assertNull(kc.icon);

        assertEquals(1, card.teams.size());
        assertEquals(2, card.teams.get(0).members.size());
        assertEquals(1, card.teams.get(0).rank);
        assertEquals(30, card.teams.get(0).points, 0.0001);
        assertEquals(1, card.teams.get(0).tilesComplete);
        assertNull(card.teams.get(0).gapToAbove);
        assertEquals(10, card.teams.get(0).leadOverBelow.points, 0.0001);
        assertEquals(1, card.teams.get(0).roster.size());
        assertEquals(1, card.teams.get(0).recentDrops.size());
        // The payload includes a proofUrl field (as a real server response might); the client model
        // has no such field at all, so this only proves it is silently ignored, never stored or thrown on.
        assertEquals("Alice", card.teams.get(0).recentDrops.get(0).rsn);

        // standings[] is the lean leaderboard: no gap/roster/recentDrops fields exist on this class.
        assertEquals(1, card.standings.size());
        assertEquals(1, card.standings.get(0).rank);
        assertEquals(30, card.standings.get(0).points, 0.0001);
        assertEquals(1, card.standings.get(0).tilesComplete);

        assertTrue(card.progress.get("t1").get("A1").complete);
        assertEquals(1, card.progress.get("t1").get("A1").drops.size());

        // A locked bounty still carries everything a numbered slot needs: number, points and the
        // released flag are real even though the title is masked and the description withheld.
        assertEquals(1, card.bounties.size());
        assertEquals(1, card.bounties.get(0).number);
        assertEquals(50, card.bounties.get(0).points, 0.0001);
        assertEquals("Bounty 1", card.bounties.get(0).title);
        assertFalse(card.bounties.get(0).released);
        assertNull(card.bounties.get(0).description);
        assertFalse(card.bounties.get(0).claimed);
        assertNull(card.bounties.get(0).claimedTeamId);
    }

    @Test public void bountyReleasedComesFromTheServerFlagAndClaimedFromClaimedTeamId()
    {
        // "released" is the server's own boolean; a non-empty claimedTeamId means claimed (that one
        // is still client-derived, since no "claimed" boolean is ever sent).
        String payload = "{\"bounties\":[{\"id\":\"b1\",\"number\":2,\"title\":\"Claimed bounty\","
            + "\"description\":\"Kill the boss\",\"released\":true,\"items\":[\"Twisted bow\"],"
            + "\"points\":25,\"releaseAt\":\"2026-09-01T00:00:00Z\","
            + "\"claimedTeamId\":\"t1\",\"claimedAt\":\"2026-09-05T00:00:00Z\"}]}";
        PlatformApiService.BingoCard card = PlatformApiService.parseBingoCard(json(payload));
        assertNotNull(card);
        assertEquals(1, card.bounties.size());
        assertTrue(card.bounties.get(0).released);
        assertEquals("Kill the boss", card.bounties.get(0).description);
        assertTrue(card.bounties.get(0).claimed);
        assertEquals("t1", card.bounties.get(0).claimedTeamId);
        assertEquals("2026-09-05T00:00:00Z", card.bounties.get(0).claimedAt);
    }

    @Test public void releasedBountyWithNoDescriptionStillReadsAsReleased()
    {
        // The old client derived "released" from description being present, so a host who released a
        // bounty without writing a description had it read as still locked.
        String payload = "{\"bounties\":[{\"id\":\"b1\",\"number\":3,\"title\":\"First Twisted bow\","
            + "\"description\":null,\"released\":true,\"points\":40,"
            + "\"releaseAt\":\"2026-09-01T00:00:00Z\",\"claimedTeamId\":null,\"claimedAt\":null}]}";
        PlatformApiService.BingoCard card = PlatformApiService.parseBingoCard(json(payload));
        assertNotNull(card);
        assertTrue(card.bounties.get(0).released);
        assertNull(card.bounties.get(0).description);
        assertFalse(card.bounties.get(0).claimed);
    }

    @Test public void missingOptionalFieldsNeverThrow()
    {
        // Only the bare minimum: an event with no other fields, no board/teams/standings/progress/bounties keys at all.
        PlatformApiService.BingoCard card = PlatformApiService.parseBingoCard(json("{\"event\":{}}"));
        assertNotNull(card);
        assertNotNull(card.event);
        assertNull(card.event.id);
        assertNull(card.event.status);
        assertEquals(0, card.board.rows);
        assertTrue(card.board.tiles.isEmpty());
        assertTrue(card.teams.isEmpty());
        assertTrue(card.standings.isEmpty());
        assertTrue(card.progress.isEmpty());
        assertTrue(card.bounties.isEmpty());
    }

    @Test public void malformedJsonNeverThrowsAndReturnsNull()
    {
        // A tile entry that isn't an object at all: parse must skip it, not throw.
        String payload = "{\"board\":{\"rows\":1,\"cols\":1,\"tiles\":[\"not an object\"]}}";
        PlatformApiService.BingoCard card = PlatformApiService.parseBingoCard(json(payload));
        assertNotNull(card);
        assertTrue(card.board.tiles.isEmpty());
    }

    // ── parseBingoPlayer (drill-in) ──
    @Test public void playerDrillInParsesTilesAndDrops()
    {
        // Real route shape (GET .../bingo/:id/players/:rsn): each drop carries tileCode/item/points/
        // proofUrl/droppedAt and NO rsn of its own, because the whole response is about one player.
        // The parser fills the requested rsn in, so the UI never renders these rows as "Unknown".
        String payload = "{\"rsn\":\"Alice\",\"teamId\":\"t1\",\"points\":42,"
            + "\"tiles\":[{\"code\":\"A1\",\"points\":30},{\"code\":\"A2\",\"points\":12}],"
            + "\"drops\":[{\"item\":\"Zulrah's scales\",\"tileCode\":\"A1\",\"points\":1,"
            + "  \"proofUrl\":\"https://discord.com/channels/1/2/3\",\"droppedAt\":\"2026-09-02T00:00:00Z\"}]}";
        PlatformApiService.BingoPlayer p = PlatformApiService.parseBingoPlayer(json(payload));
        assertNotNull(p);
        assertEquals("Alice", p.rsn);
        assertEquals("t1", p.teamId);
        assertEquals(42, p.points, 0.0001);
        assertEquals(2, p.tiles.size());
        assertEquals("A1", p.tiles.get(0).code);
        assertEquals(1, p.drops.size());
        assertEquals("Alice", p.drops.get(0).rsn);
        assertEquals("A1", p.drops.get(0).tileCode);
    }

    @Test public void playerDrillInNullRootReturnsNull()
    {
        assertNull(PlatformApiService.parseBingoPlayer(null));
    }

    @Test public void playerDrillInEmptyObjectNeverThrows()
    {
        PlatformApiService.BingoPlayer p = PlatformApiService.parseBingoPlayer(json("{}"));
        assertNotNull(p);
        assertNull(p.rsn);
        assertTrue(p.tiles.isEmpty());
        assertTrue(p.drops.isEmpty());
    }
}

package com.droplogger;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Pure parsing tests for the signups client model: PlatformApiService.parseSignups takes a
 * JsonObject and never touches the network, so a hand-built payload string exercises it exactly
 * like a real GET /clans/:slug/signups response would, including the new optional `you` object a
 * questionnaire-gated event adds ({@code you: { state, rsn, questionnaireUrl }}).
 *
 * The load-bearing assertion in this file is the one every test method that includes a
 * questionnaireUrl repeats: the parsed Signups has no field that could carry it, so there is no
 * getter to even assert against - the type system is the proof. The plugin must never display,
 * link, tooltip or open that URL (Hub rule); it parses `you.state` only.
 */
public class PlatformApiServiceSignupTest
{
    private static final Gson GSON = new Gson();

    private JsonObject json(String s) { return GSON.fromJson(s, JsonObject.class); }

    @Test public void youStatePendingParses()
    {
        String payload = "{\"open\":true,\"eventName\":\"Raid night\",\"signups\":[],"
            + "\"you\":{\"state\":\"pending\",\"rsn\":\"Woox\",\"questionnaireUrl\":\"https://forms.gle/abc123\"}}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertEquals("pending", s.youState);
        // No confirmed signups yet - a pending member is never added to the pool.
        assertTrue(s.rsns.isEmpty());
    }

    @Test public void youStateSignedUpParses()
    {
        String payload = "{\"open\":true,\"eventName\":\"Raid night\",\"signups\":[{\"rsn\":\"Woox\"}],"
            + "\"you\":{\"state\":\"signed_up\",\"rsn\":\"Woox\",\"questionnaireUrl\":null}}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertEquals("signed_up", s.youState);
        assertEquals(1, s.rsns.size());
        assertEquals("Woox", s.rsns.get(0));
    }

    @Test public void youStateNoneParses()
    {
        String payload = "{\"open\":true,\"eventName\":\"Raid night\",\"signups\":[],"
            + "\"you\":{\"state\":\"none\",\"rsn\":null,\"questionnaireUrl\":null}}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertEquals("none", s.youState);
    }

    @Test public void missingYouEntirelyDefaultsToNone()
    {
        // An older server that predates the `you` field - the plugin must keep working against it.
        String payload = "{\"open\":true,\"eventName\":\"Raid night\",\"signups\":[{\"rsn\":\"Zezima\"}]}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertEquals("none", s.youState);
        assertEquals(1, s.rsns.size());
    }

    @Test public void nullYouDefaultsToNone()
    {
        String payload = "{\"open\":true,\"eventName\":\"Raid night\",\"signups\":[],\"you\":null}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertEquals("none", s.youState);
    }

    @Test public void unrecognisedStateStringDefaultsToNone()
    {
        // A future/typo'd state string must never be treated as pending or signed_up.
        String payload = "{\"open\":true,\"signups\":[],\"you\":{\"state\":\"waitlisted\"}}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertEquals("none", s.youState);
    }

    @Test public void closedEventStillCarriesYouState()
    {
        // A closed/non-draft event returns open=false, but the viewer's own state (e.g. still
        // pending from before signups closed) is preserved rather than being reset to "none".
        String payload = "{\"open\":false,\"you\":{\"state\":\"pending\",\"questionnaireUrl\":\"https://forms.gle/xyz\"}}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertFalse(s.open);
        assertEquals("pending", s.youState);
        assertTrue(s.rsns.isEmpty());
    }

    @Test public void nullRootDefaultsToNone()
    {
        PlatformApiService.Signups s = PlatformApiService.parseSignups(null);
        assertNotNull(s);
        assertFalse(s.open);
        assertEquals("none", s.youState);
    }

    @Test public void malformedYouNeverThrows()
    {
        // "you" present but not an object at all - parse must skip it, not throw.
        String payload = "{\"open\":true,\"signups\":[],\"you\":\"not an object\"}";
        PlatformApiService.Signups s = PlatformApiService.parseSignups(json(payload));
        assertNotNull(s);
        assertEquals("none", s.youState);
    }
}

