package com.droplogger;

import com.google.gson.*;
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.util.List;

/**
 * Migration tool: serialize the hardcoded RankSystem.RANKS to the server JSON contract
 * (docs/superpowers/specs/2026-08-23-rank-editor-design.md). Run: gradlew exportRanks.
 * Writes build/ranks-export.json, which is then seeded into the API via PUT /clans/solus/ranks.
 */
public final class RankExport {
    static JsonObject check(RankSystem.Check c) {
        JsonObject o = new JsonObject();
        o.addProperty("kind", c.kind.name());
        if (c.label != null) o.addProperty("label", c.label);
        switch (c.kind) {
            case ITEMS: o.add("names", arr(c.names)); o.addProperty("k", c.value); if (c.alts != null && !c.alts.isEmpty()) o.add("alts", arr(c.alts)); break;
            case ITEMS_PREFIX: o.add("prefixes", arr(c.names)); o.addProperty("k", c.value); if (c.alts != null && !c.alts.isEmpty()) o.add("alts", arr(c.alts)); break;
            case SKILL: o.addProperty("skill", c.key); o.addProperty("level", c.value); break;
            case TOTAL: o.addProperty("min", c.value); break;
            case TOTAL_XP: o.addProperty("xp", c.value); break;
            case COMBAT_LEVEL: o.addProperty("level", c.value); break;
            case CA_TIER: o.addProperty("tier", c.key); break;
            case CA_TASK: o.addProperty("task", c.names.get(0)); break;
            case DIARY: o.addProperty("tier", c.key); o.addProperty("count", c.value); break;
            case BOSS_KC: o.addProperty("boss", c.key); o.addProperty("count", c.value); if (c.key != null) o.addProperty("key", c.key); break;
            case CLOG: o.addProperty("count", c.value); break;
            case CLOG_SLOT: o.add("names", arr(c.names)); if (c.alts != null && !c.alts.isEmpty()) o.add("alts", arr(c.alts)); break;
            case UNLOCK: o.addProperty("key", c.key); break;
            case RANK: o.addProperty("rankId", c.key); if (c.label != null) o.addProperty("name", c.label); break;
            case ALL: o.add("children", children(c.children)); break;
            case ANY: o.addProperty("need", c.need); o.add("children", children(c.children)); break;
        }
        return o;
    }
    private static JsonArray arr(List<String> xs) { JsonArray a = new JsonArray(); if (xs != null) for (String x : xs) a.add(x); return a; }
    private static JsonArray children(List<RankSystem.Check> cs) { JsonArray a = new JsonArray(); for (RankSystem.Check c : cs) a.add(check(c)); return a; }

    public static void main(String[] args) throws Exception {
        JsonArray ranks = new JsonArray();
        for (RankSystem.Rank r : RankSystem.RANKS) {
            JsonObject ro = new JsonObject();
            ro.addProperty("id", r.id); ro.addProperty("name", r.name);
            ro.addProperty("path", r.path); ro.addProperty("desc", r.desc);
            JsonArray req = new JsonArray(); for (String s : r.requires) req.add(s); ro.add("requires", req);
            JsonArray groups = new JsonArray();
            for (RankSystem.Group g : r.groups) {
                JsonObject go = new JsonObject();
                go.addProperty("label", g.label); go.addProperty("need", g.need);
                JsonArray opts = new JsonArray(); for (RankSystem.Check c : g.options) opts.add(check(c));
                go.add("options", opts); groups.add(go);
            }
            ro.add("groups", groups); ranks.add(ro);
        }
        try (Writer w = new OutputStreamWriter(new FileOutputStream("build/ranks-export.json"), StandardCharsets.UTF_8)) {
            new GsonBuilder().setPrettyPrinting().create().toJson(ranks, w);
        }
        System.out.println("RANK_EXPORT: " + ranks.size() + " ranks -> build/ranks-export.json");
    }
}

package com.droplogger;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.*;

/** Hard-mode raid KC (CoX CM, ToB HM, ToA Expert) counts 1.5x toward raid KC requirements. */
public class RankRaidKcWeightTest
{
    private static final String COX = "chambers_of_xeric", COX_CM = "chambers_of_xeric:_challenge_mode";
    private static final String TOB = "theatre_of_blood", TOB_HM = "theatre_of_blood:_hard_mode";
    private static final String TOA = "tombs_of_amascut", TOA_EX = "tombs_of_amascut:_expert_mode";

    private static RankSystem.PlayerSnapshot snap(Object... kv)
    {
        RankSystem.PlayerSnapshot s = new RankSystem.PlayerSnapshot();
        for (int i = 0; i < kv.length; i += 2) s.kc.put((String) kv[i], (Integer) kv[i + 1]);
        return s;
    }

    private static boolean meets(String key, int count, RankSystem.PlayerSnapshot s)
    {
        return RankSystem.evalCheck(RankSystem.Check.kc("req", count, key), s);
    }

    @Test public void seventyFiveCmAloneMeetsHundredRaids()
    {
        assertTrue(meets("raids_combined", 100, snap(COX_CM, 75)));
        assertTrue(meets("cox_total", 100, snap(COX_CM, 75)));
        assertEquals(112.5, RankSystem.effectiveKc("raids_combined", snap(COX_CM, 75).kc), 0.0);
    }

    @Test public void fiftyNormalPlusThirtyFourCmMeetsHundred()
    {
        assertTrue(meets("cox_total", 100, snap(COX, 50, COX_CM, 34)));     // 50 + 51 = 101
        assertTrue(meets("raids_combined", 100, snap(COX, 50, COX_CM, 34)));
    }

    @Test public void fiftyNormalPlusThirtyThreeCmDoesNotMeetHundred()
    {
        // 50 + 49.5 = 99.5: compared unrounded, so it falls short.
        assertFalse(meets("cox_total", 100, snap(COX, 50, COX_CM, 33)));
        assertFalse(meets("raids_combined", 100, snap(COX, 50, COX_CM, 33)));
        assertEquals(99.5, RankSystem.effectiveKc("cox_total", snap(COX, 50, COX_CM, 33).kc), 0.0);
    }

    @Test public void tobHardModeWeightsTheSame()
    {
        assertTrue(meets("tob_total", 100, snap(TOB_HM, 75)));
        assertTrue(meets("tob_total", 100, snap(TOB, 50, TOB_HM, 34)));
        assertFalse(meets("tob_total", 100, snap(TOB, 50, TOB_HM, 33)));
        assertTrue(meets(TOB, 100, snap(TOB, 50, TOB_HM, 34)));
    }

    @Test public void toaExpertWeightsTheSame()
    {
        assertTrue(meets("toa_total", 100, snap(TOA_EX, 75)));
        assertTrue(meets("toa_total", 100, snap(TOA, 50, TOA_EX, 34)));
        assertFalse(meets("toa_total", 100, snap(TOA, 50, TOA_EX, 33)));
        assertTrue(meets(TOA, 100, snap(TOA, 50, TOA_EX, 34)));
    }

    @Test public void combinedSumsAllThreeWeighted()
    {
        // 10 + 1.5*10 + 10 + 1.5*10 + 10 + 1.5*10 = 75
        RankSystem.PlayerSnapshot s = snap(COX, 10, COX_CM, 10, TOB, 10, TOB_HM, 10, TOA, 10, TOA_EX, 10);
        assertEquals(75.0, RankSystem.effectiveKc("raids_combined", s.kc), 0.0);
        assertTrue(meets("raids_combined", 75, s));
        assertFalse(meets("raids_combined", 76, s));
        // Normal KC alone still counts 1x, exactly as before.
        assertTrue(meets("raids_combined", 100, snap(COX, 40, TOB, 30, TOA, 30)));
        assertFalse(meets("raids_combined", 100, snap(COX, 40, TOB, 30, TOA, 29)));
    }

    @Test public void hardModeSpecificRequirementsAreNotWeighted()
    {
        assertTrue(meets(COX_CM, 50, snap(COX_CM, 50)));
        assertFalse(meets(COX_CM, 50, snap(COX_CM, 49, COX, 500)));
        assertFalse(meets(TOB_HM, 50, snap(TOB_HM, 34)));   // 34 HM is 34, not 51
        assertFalse(meets(TOA_EX, 50, snap(TOA_EX, 34)));
        assertEquals(34.0, RankSystem.effectiveKc(TOA_EX, snap(TOA_EX, 34).kc), 0.0);
    }

    @Test public void nonRaidBossKcUnchanged()
    {
        assertTrue(meets("zulrah", 512, snap("zulrah", 512)));
        assertFalse(meets("zulrah", 512, snap("zulrah", 511, COX_CM, 1000)));
        assertTrue(meets("god_wars_dungeon", 508, snap("god_wars_dungeon", 508)));
        assertFalse(meets("vorkath", 1, snap()));
    }

    @Test public void keysAreCaseInsensitive()
    {
        assertTrue(meets("RAIDS_COMBINED", 100, snap(COX_CM, 75)));
        assertTrue(meets("Chambers_Of_Xeric", 100, snap(COX_CM, 75)));
    }

    @Test public void serverJsonRequirementIsWeighted()
    {
        // Same shape the website rank editor saves (BOSS_KC with an explicit key).
        String json = "[{\"id\":\"r\",\"name\":\"R\",\"path\":\"\",\"desc\":\"\",\"requires\":[],"
            + "\"groups\":[{\"label\":\"g\",\"need\":1,\"options\":["
            + "{\"kind\":\"BOSS_KC\",\"label\":\"100 combined raid KC\",\"boss\":\"raids_combined\",\"count\":100,\"key\":\"raids_combined\"}"
            + "]}]}]";
        List<RankSystem.Rank> ranks = RankSystem.parseRanks(json);
        RankSystem.Check c = ranks.get(0).groups.get(0).options.get(0);
        assertTrue(RankSystem.evalCheck(c, snap(TOB_HM, 75)));
        assertFalse(RankSystem.evalCheck(c, snap(TOB, 50, TOB_HM, 33)));
    }
}

package com.droplogger;

import com.google.gson.GsonBuilder;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.List;

/**
 * Verifies RankSystem.parseRanks is the exact inverse of RankExport: serialize the bundled
 * RANKS -> A, parse A back into Rank objects, re-serialize -> B, assert A equals B.
 * Run: gradlew rankRoundTrip
 */
public final class RankRoundTrip {
    private static JsonArray serialize(List<RankSystem.Rank> ranks) {
        JsonArray arr = new JsonArray();
        for (RankSystem.Rank r : ranks) {
            JsonObject ro = new JsonObject();
            ro.addProperty("id", r.id); ro.addProperty("name", r.name);
            ro.addProperty("path", r.path); ro.addProperty("desc", r.desc);
            JsonArray req = new JsonArray(); for (String s : r.requires) req.add(s); ro.add("requires", req);
            JsonArray groups = new JsonArray();
            for (RankSystem.Group g : r.groups) {
                JsonObject go = new JsonObject();
                go.addProperty("label", g.label); go.addProperty("need", g.need);
                JsonArray opts = new JsonArray(); for (RankSystem.Check c : g.options) opts.add(RankExport.check(c));
                go.add("options", opts); groups.add(go);
            }
            ro.add("groups", groups); arr.add(ro);
        }
        return arr;
    }

    public static void main(String[] args) throws Exception {
        JsonArray a = serialize(RankSystem.RANKS);
        String aStr = new GsonBuilder().create().toJson(a);
        List<RankSystem.Rank> parsed = RankSystem.parseRanks(aStr);
        JsonArray b = serialize(parsed);
        String bStr = new GsonBuilder().create().toJson(b);
        if (!aStr.equals(bStr)) {
            System.out.println("ROUNDTRIP_FAIL");
            // find first divergence
            int n = Math.min(aStr.length(), bStr.length());
            int i = 0; while (i < n && aStr.charAt(i) == bStr.charAt(i)) i++;
            int from = Math.max(0, i - 60);
            System.out.println("A: ..." + aStr.substring(from, Math.min(aStr.length(), i + 60)));
            System.out.println("B: ..." + bStr.substring(from, Math.min(bStr.length(), i + 60)));
            System.exit(1);
        }
        System.out.println("ROUNDTRIP_OK: " + parsed.size() + " ranks, " + aStr.length() + " chars identical");

        // Alternates: owning only a hidden alt (an upgrade) must satisfy the check, and the alt must
        // survive a serialize->parse round-trip.
        String altJson = "[{\"id\":\"t\",\"name\":\"T\",\"path\":\"\",\"desc\":\"\",\"requires\":[],"
            + "\"groups\":[{\"label\":\"ring\",\"need\":1,\"options\":["
            + "{\"kind\":\"ITEMS\",\"label\":\"A ring\",\"names\":[\"berserker ring (i)\"],\"k\":1,\"alts\":[\"ultor ring\"]}]}]}]";
        RankSystem.Rank altRank = RankSystem.parseRanks(altJson).get(0);
        if (altRank.groups.get(0).options.get(0).alts.size() != 1) { System.out.println("ALTS_PARSE_FAIL"); System.exit(1); }
        RankSystem.PlayerSnapshot snap = new RankSystem.PlayerSnapshot();
        snap.ownedItems.add("ultor ring"); // owns only the alt, not the named item
        RankSystem.RankStatus st = RankSystem.evaluate(altRank, snap);
        if (!st.eligible) { System.out.println("ALTS_EVAL_FAIL: owning the alt did not satisfy the check"); System.exit(1); }
        // And re-serializing keeps the alt.
        if (!new GsonBuilder().create().toJson(serialize(RankSystem.parseRanks(altJson))).contains("ultor ring")) {
            System.out.println("ALTS_REEXPORT_FAIL"); System.exit(1);
        }
        System.out.println("ALTS_OK: owned alt satisfied the check + round-tripped");
    }
}

package com.droplogger;

import java.awt.Color;
import org.junit.Test;
import static org.junit.Assert.*;

public class TeamColorsTest
{
    @Test public void readsHex() { assertEquals(new Color(0x1E88E5), TeamColors.parse("#1E88E5")); }
    @Test public void readsOldNames() { assertEquals(new Color(0xE53935), TeamColors.parse("red")); }
    @Test public void namesAreCaseInsensitive() { assertEquals(new Color(0xE53935), TeamColors.parse("Red")); }
    @Test public void unknownIsNull() { assertNull(TeamColors.parse("chartreuse")); }
    @Test public void badHexIsNull() { assertNull(TeamColors.parse("#zzz")); }
    @Test public void blankIsNull() { assertNull(TeamColors.parse("  ")); assertNull(TeamColors.parse(null)); }
}
